  '{"schema_version":"1.0.0","case_id":"chan-tam-thong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau ngực dữ dội lúc rạng sáng","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":62,"sex":"nam","patient_label":"Ông Trần Văn Hòa"},"presentation":{"intro":"Phòng cấp cứu, 02:10. Ông được vợ đưa vào vì đau ngực dữ dội 40 phút, vã mồ hôi, sợ hãi.","place":"Phòng cấp cứu","clock":"02:10","night":true},"vitals":{"hr":104,"sbp":90,"dbp":60,"rr":24,"temperature_c":36.8,"spo2":88},"history":[{"question":"Đau ngực như thế nào? Lan đi đâu?","response":"Đau như bị đè nặng sau xương ức, lan lên vai trái và hàm. Rất dữ dội."},{"question":"Đau bắt đầu từ lúc nào? Đang làm gì?","response":"Khoảng 40 phút trước, đang ngủ thì đau đột ngột, không đỡ khi nghỉ."},{"question":"Tiền sử bệnh, thói quen?","response":"Tăng huyết áp, đái tháo đường, hút thuốc 30 năm."},{"question":"Có dị ứng thuốc, đang dùng thuốc chống đông không?","response":"Không dị ứng thuốc, không dùng thuốc chống đông."},{"question":"Có khó thở, ngất, buồn nôn không?","response":"Khó thở, buồn nôn, lạnh chân tay, mồ hôi lạnh. Chưa ngất."},{"question":"Đau có thay đổi khi hít sâu hoặc đổi tư thế không?","response":"Không thay đổi theo hơi thở hay tư thế."},{"question":"Có đau lưng xé từ ngực ra sau không?","response":"Không, đau không xé ra sau lưng."}],"examination":[{"group":"K","item":"Thần sắc","finding":"Mặt xám xanh, môi tím nhạt, vã mồ hôi lạnh, vẻ mặt hoảng sợ."},{"group":"K","item":"Mạch","finding":"Mạch nhanh, nhỏ."},{"group":"K","item":"Sờ tay chân","finding":"Tay chân lạnh ẩm."},{"group":"K","item":"Nghe tim phổi","finding":"Tim nhanh, đều, không âm thổi. Phổi có ít ran ẩm hai đáy."},{"group":"K","item":"Đo huyết áp hai tay","finding":"Hai tay chênh nhau không đáng kể."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo","duration_minutes":2,"result":"ST chênh lên ≥ 2 mm ở V2–V5: nhồi máu cơ tim cấp thành trước."},{"name":"Troponin hs","duration_minutes":15,"result":"Tăng cao. Không cần chờ kết quả để quyết định tái tưới máu."},{"name":"Siêu âm tim tại giường","duration_minutes":5,"result":"Giảm động vùng mỏm và thành trước, EF khoảng 40%."},{"name":"Công thức máu, điện giải, đông máu","duration_minutes":10,"result":"Chưa thấy bất thường đáng kể."},{"name":"X-quang ngực tại giường","duration_minutes":10,"result":"Bóng tim không to, phổi ứ huyết nhẹ."},{"name":"CT sọ não","duration_minutes":20,"result":"Không có chỉ định. Làm mất thời gian vàng."}],"choices":{"diagnosis":{"ydx":["Bóc tách động mạch chủ","Viêm màng ngoài tim cấp","Nhồi máu cơ tim cấp ST chênh lên (STEMI)","Đau thắt ngực ổn định","Trào ngược dạ dày thực quản"]},"actions":["Giảm đau bằng opioid liều nhỏ tĩnh mạch","Hội chẩn tim mạch, kích hoạt can thiệp mạch vành thì đầu","Cho nhai aspirin 300 mg","Cho thuốc hạ áp mạnh","Gắn monitor, thở oxy qua mặt nạ","Lập đường truyền tĩnh mạch","Dùng thuốc chống đông/kháng kết tập thứ hai theo phác đồ"]}}'::jsonb,
  '7352280d0fe0d6e988ad6ca159c976cdb8e3617ade827d35a043eea071d04a77'
)
