  '{"schema_version":"1.0.0","case_id":"chan-tam-thong","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-acs-accaha-2025","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/40014670/","title":"ACC/AHA/ACEP/NAEMSP/SCAI, Guideline for the Management of Patients With Acute Coronary Syndromes, 2025.","organization":null,"year_version":null,"citation":"ACC/AHA/ACEP/NAEMSP/SCAI, Guideline for the Management of Patients With Acute Coronary Syndromes, 2025.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhồi máu cơ tim cấp ST chênh lên (STEMI)","credit":"full"},{"text":"Đau thắt ngực ổn định","credit":"none"},{"text":"Bóc tách động mạch chủ","credit":"none"},{"text":"Viêm màng ngoài tim cấp","credit":"none"},{"text":"Trào ngược dạ dày thực quản","credit":"none"}]},"action_options":[{"text":"Gắn monitor, thở oxy qua mặt nạ","time_minutes":1,"grade":"critical","rationale":"SpO2 88% cần bù oxy."},{"text":"Lập đường truyền tĩnh mạch","time_minutes":2,"grade":"critical","rationale":"Chuẩn bị thuốc và theo dõi."},{"text":"Cho nhai aspirin 300 mg","time_minutes":1,"grade":"critical","rationale":"Không dị ứng, chỉ định chuẩn trong STEMI."},{"text":"Hội chẩn tim mạch, kích hoạt can thiệp mạch vành thì đầu","time_minutes":3,"grade":"critical","rationale":"Tái tưới máu sớm quyết định sống còn."},{"text":"Giảm đau bằng opioid liều nhỏ tĩnh mạch","time_minutes":1,"grade":"recommended","rationale":"Giảm đau khi đau nhiều, theo dõi huyết áp."},{"text":"Dùng thuốc chống đông/kháng kết tập thứ hai theo phác đồ","time_minutes":2,"grade":"recommended","rationale":"Theo hướng dẫn tim mạch."},{"text":"Cho thuốc hạ áp mạnh","time_minutes":2,"grade":"harmful","rationale":"Huyết áp đang thấp 90/60, có thể gây sốc."}],"teaching_explanation":"STEMI là cấp cứu: ưu tiên tái tưới máu sớm. Đau ngực dữ dội, vã mồ hôi lạnh và tay chân lạnh gợi nhồi máu cơ tim cấp. Sai lầm nguy hiểm nhất là trì hoãn can thiệp để dùng biện pháp khác."}'::jsonb,
