  '{"schema_version":"1.0.0","case_id":"trung-phong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Méo miệng, liệt nửa người đột ngột","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":68,"sex":"nữ","patient_label":"Bà Lê Thị Mận"},"presentation":{"intro":"Phòng cấp cứu, 08:00. Con gái đưa bà vào vì sáng nay phát hiện méo miệng, yếu nửa người phải, nói khó. Lần cuối thấy bà bình thường là 07:00.","place":"Phòng cấp cứu","clock":"08:00","night":false},"vitals":{"hr":92,"sbp":190,"dbp":105,"rr":18,"temperature_c":37,"spo2":96},"history":[{"question":"Triệu chứng bắt đầu lúc nào, có đột ngột không?","response":"Đột ngột, khoảng 40 phút trước, lúc đang đánh răng."},{"question":"Tiền sử bệnh?","response":"Tăng huyết áp nhiều năm, thỉnh thoảng hồi hộp, chưa điều trị đều."},{"question":"Có dùng thuốc chống đông, có chấn thương đầu gần đây không?","response":"Không dùng thuốc chống đông. Không ngã, không chấn thương."},{"question":"Có đau đầu, nôn không?","response":"Đau đầu nhẹ, nôn một lần."},{"question":"Đại tiện, đờm?","response":"Táo bón 3 ngày, đờm nhiều."},{"question":"Ăn uống thường ngày?","response":"Thích ăn béo ngọt, ít vận động."}],"examination":[{"group":"K","item":"Ý thức, thang điểm đột quỵ (NIHSS)","finding":"Tỉnh, lơ mơ nhẹ, nói ngọng. NIHSS khoảng 12."},{"group":"K","item":"Mặt","finding":"Méo miệng sang trái, nếp mũi má phải mờ (liệt VII trung ương phải)."},{"group":"K","item":"Vận động tay chân","finding":"Tay chân phải lực cơ 2/5, bên trái 5/5."},{"group":"K","item":"Mạch","finding":"Mạch không đều."},{"group":"K","item":"Tiếng đờm","finding":"Họng khò khè, đờm nhiều."}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":1,"result":"7,2 mmol/L."},{"name":"CT sọ không cản quang","duration_minutes":15,"result":"Không xuất huyết. Chưa thấy vùng giảm tỷ trọng rõ."},{"name":"Điện tâm đồ","duration_minutes":3,"result":"Rung nhĩ, đáp ứng thất hơi nhanh."},{"name":"Công thức máu, đông máu, điện giải","duration_minutes":10,"result":"INR 1,0. Tiểu cầu bình thường."},{"name":"MRI sọ não","duration_minutes":40,"result":"Hạn chế khuếch tán vùng động mạch não giữa trái. Không nên chờ MRI để quyết định."},{"name":"Chọc dịch não tủy","duration_minutes":20,"result":"Không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Xuất huyết não","Liệt Bell (liệt VII ngoại biên)","Cơn thiếu máu não thoáng qua","Đột quỵ nhồi máu não cấp (nghi do rung nhĩ)"]},"actions":["Bảo đảm đường thở, theo dõi monitor và chọn tư thế đầu giường theo tình trạng hô hấp, nuốt, huyết động","Hội chẩn quyết định tiêu sợi huyết hoặc lấy huyết khối cơ học","Kích hoạt báo động đột quỵ, hội chẩn thần kinh","Hạ huyết áp nhanh về 120/80","Cho aspirin và heparin ngay trước khi có CT","Quản lý huyết áp theo chiến lược tái tưới máu"]}}'::jsonb,
