values (
  'trung-phong',
  '{"schema_version":"1.0.0","case_id":"trung-phong","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ais-aha-2026","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/41582814/","title":"AHA/ASA, Guideline for the Early Management of Patients With Acute Ischemic Stroke, 2026.","organization":null,"year_version":null,"citation":"AHA/ASA, Guideline for the Early Management of Patients With Acute Ischemic Stroke, 2026.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ nhồi máu não cấp (nghi do rung nhĩ)","credit":"full"},{"text":"Xuất huyết não","credit":"none"},{"text":"Cơn thiếu máu não thoáng qua","credit":"none"},{"text":"Liệt Bell (liệt VII ngoại biên)","credit":"none"}]},"action_options":[{"text":"Kích hoạt báo động đột quỵ, hội chẩn thần kinh","time_minutes":2,"grade":"critical","rationale":"Mỗi phút trôi qua mất tế bào thần kinh."},{"text":"Bảo đảm đường thở, theo dõi monitor và chọn tư thế đầu giường theo tình trạng hô hấp, nuốt, huyết động","time_minutes":1,"grade":"critical","rationale":"Không có lợi ích chức năng đã chứng minh cho việc mặc định đầu cao 30° ở mọi đột quỵ thiếu máu; tư thế cần cá thể hóa."},{"text":"Hội chẩn quyết định tiêu sợi huyết hoặc lấy huyết khối cơ học","time_minutes":3,"grade":"critical","rationale":"Chỉ sau khi CT loại trừ xuất huyết và còn trong cửa sổ thời gian."},{"text":"Quản lý huyết áp theo chiến lược tái tưới máu","time_minutes":1,"grade":"recommended","rationale":"Nếu đủ điều kiện tiêu sợi huyết tĩnh mạch, cần đạt <185/110 mmHg trước điều trị; nếu không tái tưới máu và không có chỉ định khác, tránh hạ áp tích cực quá mức."},{"text":"Hạ huyết áp nhanh về 120/80","time_minutes":2,"grade":"harmful","rationale":"Có thể làm vùng thiếu máu lan rộng."},{"text":"Cho aspirin và heparin ngay trước khi có CT","time_minutes":2,"grade":"harmful","rationale":"Chưa loại trừ xuất huyết."}],"teaching_explanation":"Thứ tự đúng: ổn định ABC, xác định thời điểm cuối bình thường, đo glucose, chụp não khẩn và quyết định tái thông. Nếu dự kiến tiêu sợi huyết tĩnh mạch, huyết áp cần được kiểm soát theo ngưỡng của phác đồ (thường <185/110 mmHg trước điều trị). Không mặc định đầu cao 30° cho mọi trường hợp; tư thế đầu giường cá thể hóa."}'::jsonb,
