  '{"schema_version":"1.0.0","case_id":"trung-thu","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Công nhân gục giữa trưa nắng","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":30,"sex":"nam","patient_label":"Anh Nguyễn Văn Khoa"},"presentation":{"intro":"Phòng cấp cứu, 13:40. Anh làm việc ngoài trời 5 giờ, đồng nghiệp thấy gục xuống, lú lẫn, da nóng.","place":"Phòng cấp cứu","clock":"13:40","night":false},"vitals":{"hr":128,"sbp":95,"dbp":55,"rr":28,"temperature_c":40.5,"spo2":95},"history":[{"question":"Làm việc ngoài nắng bao lâu, có uống đủ nước không?","response":"Khoảng 5 giờ liền, uống rất ít nước."},{"question":"Lúc đầu có ra mồ hôi nhiều không? Bây giờ thì sao?","response":"Lúc đầu vã mồ hôi nhiều, bây giờ da khô nóng, không ra mồ hôi."},{"question":"Có ngất, co giật, lú lẫn không?","response":"Ngất một lần, hiện nói sảng, lú lẫn."},{"question":"Tiền sử bệnh, thuốc, rượu?","response":"Không bệnh nền, không uống rượu hay thuốc."},{"question":"Nước tiểu?","response":"Ít, màu sẫm."},{"question":"Có nôn, tiêu chảy không?","response":"Nôn hai lần."}],"examination":[{"group":"K","item":"Da và thần sắc","finding":"Da đỏ, nóng khô, mặt đỏ, thở nhanh nông."},{"group":"K","item":"Ý thức","finding":"Lơ mơ, nói sảng, đáp ứng chậm."},{"group":"K","item":"Mạch","finding":"Mạch nhanh."},{"group":"K","item":"Khám tim phổi, bụng","finding":"Tim nhanh đều. Phổi thông khí đều. Bụng mềm."}],"investigations":[{"name":"Nhiệt độ trung tâm (trực tràng)","duration_minutes":1,"result":"40,6 độ C."},{"name":"Điện giải, creatinin, CK, men gan","duration_minutes":10,"result":"Na 148, K 3,2, creatinin 1,6, CK 4.800. Tổn thương thận cấp nhẹ, tiêu cơ vân."},{"name":"Đường huyết mao mạch","duration_minutes":1,"result":"4,8 mmol/L."},{"name":"Khí máu động mạch","duration_minutes":5,"result":"Nhiễm toan chuyển hóa."},{"name":"Điện tâm đồ","duration_minutes":3,"result":"Nhịp nhanh xoang."},{"name":"CT sọ não","duration_minutes":20,"result":"Không có chấn thương đầu. Làm chậm việc hạ nhiệt."}],"choices":{"diagnosis":{"ydx":["Viêm màng não","Đột quỵ nhiệt (say nắng nặng)","Hạ đường huyết","Kiệt sức do nóng","Cơn bão giáp"]},"actions":["Truyền dịch tĩnh mạch natri clorid 0,9% hoặc Ringer lactat","Cho paracetamol hạ sốt là chính","Ủ ấm, đắp chăn dày cho ra mồ hôi","Gắn monitor, đo nhiệt độ trung tâm liên tục","Chuyển vào nơi mát, cởi quần áo, phun sương và quạt, chườm đá cổ nách bẹn","Bồi phụ điện giải theo kết quả xét nghiệm","Ép uống nhiều nước lạnh nhanh khi đang lơ mơ"]}}'::jsonb,
