values (
  'trung-thu',
  '{"schema_version":"1.0.0","case_id":"trung-thu","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-heat-wms-2024","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/38425235/","title":"Wilderness Medical Society, Clinical Practice Guidelines for the Prevention and Treatment of Heat Illness: 2024 Update, 2024.","organization":null,"year_version":null,"citation":"Wilderness Medical Society, Clinical Practice Guidelines for the Prevention and Treatment of Heat Illness: 2024 Update, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,4],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ nhiệt (say nắng nặng)","credit":"full"},{"text":"Kiệt sức do nóng","credit":"none"},{"text":"Viêm màng não","credit":"none"},{"text":"Hạ đường huyết","credit":"none"},{"text":"Cơn bão giáp","credit":"none"}]},"action_options":[{"text":"Chuyển vào nơi mát, cởi quần áo, phun sương và quạt, chườm đá cổ nách bẹn","time_minutes":2,"grade":"critical","rationale":"Hạ nhiệt tích cực là điều trị quyết định."},{"text":"Truyền dịch tĩnh mạch natri clorid 0,9% hoặc Ringer lactat","time_minutes":2,"grade":"critical","rationale":"Bù dịch, hỗ trợ tuần hoàn và thận."},{"text":"Gắn monitor, đo nhiệt độ trung tâm liên tục","time_minutes":1,"grade":"critical","rationale":"Theo dõi đáp ứng điều trị."},{"text":"Bồi phụ điện giải theo kết quả xét nghiệm","time_minutes":2,"grade":"recommended","rationale":"Hạ natri, kali theo chỉ định."},{"text":"Cho paracetamol hạ sốt là chính","time_minutes":1,"grade":"waste","rationale":"Thuốc hạ sốt không hiệu quả trong đột quỵ nhiệt."},{"text":"Ủ ấm, đắp chăn dày cho ra mồ hôi","time_minutes":2,"grade":"harmful","rationale":"Làm nhiệt độ tăng thêm."},{"text":"Ép uống nhiều nước lạnh nhanh khi đang lơ mơ","time_minutes":2,"grade":"harmful","rationale":"Nguy cơ sặc."}],"teaching_explanation":"Đột quỵ nhiệt là cấp cứu hạ nhiệt: mỗi phút nhiệt độ trung tâm cao đều gây tổn thương. Ưu tiên làm mát nhanh, bù dịch và theo dõi biến chứng đa cơ quan."}'::jsonb,
  '338d3a4b2e193698a6bc0b1515fb9d6b15745b5c51044b8eedf48568784072e6'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'hao-suyen',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"hao-suyen","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khó thở khò khè, xịt thuốc không đỡ","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":26,"sex":"nam","patient_label":"Anh Võ Minh Quân"},"presentation":{"intro":"Phòng cấp cứu, 21:30. Anh ngồi chống tay hai bên, thở khò khè nặng nhọc, nói từng cụm ngắn. Đã xịt thuốc cắt cơn nhiều lần ở nhà.","place":"Phòng cấp cứu","clock":"21:30","night":true},"vitals":{"hr":118,"sbp":130,"dbp":80,"rr":30,"temperature_c":37,"spo2":89},"history":[{"question":"Khó thở khò khè bắt đầu từ lúc nào?","response":"Khoảng 2 giờ nay, tăng dần sau khi hít khói bụi trời lạnh."},{"question":"Tiền sử hen? Đã dùng thuốc gì?","response":"Hen từ nhỏ. Đã xịt salbutamol 6 lần, không đỡ."},{"question":"Có từng nhập viện, đặt ống thở vì hen không?","response":"Một lần cách đây 2 năm phải vào hồi sức."},{"question":"Có sốt, ho đờm màu gì?","response":"Không sốt, ho ít đờm trắng loãng."},{"question":"Có dùng thuốc chẹn beta, aspirin, kháng viêm giảm đau gần đây không?","response":"Không."},{"question":"Có dị ứng thức ăn, thuốc không?","response":"Dị ứng phấn hoa, không dị ứng thuốc."}],"examination":[{"group":"K","item":"Tư thế, nói chuyện, cơ hô hấp phụ","finding":"Ngồi chống tay, nói được 2-3 từ mỗi hơi, co kéo cơ ức đòn chũm và liên sườn."},{"group":"K","item":"Nghe phổi","finding":"Ran rít, ran ngáy lan tỏa hai phế trường. Rì rào phế nang giảm. Chưa có phổi câm."},{"group":"K","item":"Lưu lượng đỉnh (PEF)","finding":"Khoảng 35% giá trị dự đoán."},{"group":"K","item":"Sắc mặt, môi","finding":"Vã mồ hôi, môi tím nhẹ, sợ lạnh."},{"group":"K","item":"Tiếng thở, tiếng ho","finding":"Thở rít khò khè nghe rõ, ho ít, đờm trắng loãng."},{"group":"K","item":"Mạch","finding":"Mạch nhanh."}],"investigations":[{"name":"Khí máu động mạch","duration_minutes":5,"result":"pH 7,42, PaO2 58, PaCO2 36 mmHg. PaCO2 bình thường trong cơn nặng là dấu hiệu sắp kiệt sức."},{"name":"X-quang ngực tại giường","duration_minutes":10,"result":"Phổi tăng sáng, không tràn khí màng phổi, không viêm phổi."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu bình thường, bạch cầu ái toan hơi tăng."},{"name":"Điện tâm đồ","duration_minutes":3,"result":"Nhịp nhanh xoang."},{"name":"CT ngực","duration_minutes":30,"result":"Không có chỉ định lúc này, làm chậm điều trị."}],"choices":{"diagnosis":{"ydx":["Phù phổi cấp","Thuyên tắc phổi","Cơn hen phế quản cấp mức nặng","Dị vật đường thở","Đợt cấp COPD"]},"actions":["Corticoid toàn thân sớm","Theo dõi PEF, nhịp thở, khí máu lặp lại","Kháng sinh thường quy","Cho thuốc chẹn beta để giảm nhịp tim nhanh","Cho ngồi, thở oxy, gắn monitor SpO2 mục tiêu 93-95%","Khí dung salbutamol (có thể phối hợp ipratropium) liên tục","Truyền magnesi sulfat nếu không đáp ứng sau điều trị đầu","Cho thuốc an thần (diazepam) để bớt vật vã"]}}'::jsonb,
  '3b37ae6e4c636e7b27e55e23572948beaa21046aac647fc0a26ca7add7f40632'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'hao-suyen',
  '{"schema_version":"1.0.0","case_id":"hao-suyen","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-gina-2025-2dd5483279cd","resource_type":"guideline","source":"https://ginasthma.org/wp-content/uploads/2025/11/GINA-Summary-Guide-2025-WEB_FINAL-WMS.pdf","title":"Global Initiative for Asthma, Summary Guide for Asthma Management and Prevention, 2025.","organization":null,"year_version":null,"citation":"Global Initiative for Asthma, Summary Guide for Asthma Management and Prevention, 2025.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,2,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Cơn hen phế quản cấp mức nặng","credit":"full"},{"text":"Đợt cấp COPD","credit":"none"},{"text":"Phù phổi cấp","credit":"none"},{"text":"Thuyên tắc phổi","credit":"none"},{"text":"Dị vật đường thở","credit":"none"}]},"action_options":[{"text":"Cho ngồi, thở oxy, gắn monitor SpO2 mục tiêu 93-95%","time_minutes":1,"grade":"critical","rationale":"SpO2 89% cần bù oxy ngay."},{"text":"Khí dung salbutamol (có thể phối hợp ipratropium) liên tục","time_minutes":2,"grade":"critical","rationale":"Thuốc giãn phế quản là điều trị cắt cơn chủ lực."},{"text":"Corticoid toàn thân sớm","time_minutes":2,"grade":"critical","rationale":"Giảm viêm đường thở, phát huy tác dụng sau vài giờ nên cho sớm."},{"text":"Theo dõi PEF, nhịp thở, khí máu lặp lại","time_minutes":2,"grade":"recommended","rationale":"Phát hiện sớm dấu hiệu kiệt sức."},{"text":"Truyền magnesi sulfat nếu không đáp ứng sau điều trị đầu","time_minutes":2,"grade":"recommended","rationale":"Lựa chọn khi cơn nặng không đáp ứng."},{"text":"Kháng sinh thường quy","time_minutes":1,"grade":"waste","rationale":"Không sốt, đờm trắng loãng, không có bằng chứng nhiễm khuẩn."},{"text":"Cho thuốc an thần (diazepam) để bớt vật vã","time_minutes":1,"grade":"harmful","rationale":"Ức chế hô hấp, nguy hiểm trong cơn hen nặng."},{"text":"Cho thuốc chẹn beta để giảm nhịp tim nhanh","time_minutes":1,"grade":"harmful","rationale":"Chống chỉ định trong hen, gây co thắt phế quản."}],"teaching_explanation":"Cơn hen nặng là cấp cứu hô hấp: oxy, giãn phế quản, corticoid trước. PaCO2 bình thường trong cơn nặng là dấu hiệu nguy hiểm. Tiền sử từng vào hồi sức là yếu tố nguy cơ tử vong."}'::jsonb,
  '64895cfbb5f1c1eaf946a4cad3d38af5d0358742b99852be6443def6daf9a96c'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'vi-quan-thong',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"vi-quan-thong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thượng vị âm ỉ","setting":"phongkham","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":52,"sex":"nữ","patient_label":"Bà Lê Thị Hạnh"},"presentation":{"intro":"Khoa Nội YHCT, giường 12. Bà đến khám vì đau vùng thượng vị 3 tháng, đã tự mua thuốc giảm đau uống nhiều lần.","place":"Phòng khám Nội YHCT","clock":"09:15","night":false},"vitals":{"hr":78,"sbp":110,"dbp":70,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Đau ở đâu, đau như thế nào?","response":"Đau âm ỉ vùng thượng vị khoảng 3 tháng nay, lúc đau lúc không, không đau dữ dội."},{"question":"Chườm ấm hoặc ăn uống có làm đỡ đau không?","response":"Uống nước ấm, chườm ấm, xoa bụng thì đỡ. Lúc đói đau nhiều hơn, ăn vào đỡ một chút."},{"question":"Có ợ hơi, buồn nôn hay nôn không?","response":"Hay ợ hơi, thỉnh thoảng nôn ra nước trong. Không nôn ra máu."},{"question":"Đại tiện thế nào? Phân màu gì?","response":"Phân nhão, 2 lần mỗi ngày, màu vàng nâu, không đen."},{"question":"Có sụt cân, nuốt nghẹn không?","response":"Không sụt cân, không nuốt nghẹn."},{"question":"Cảm giác nóng lạnh ra sao?","response":"Sợ lạnh, tay chân lạnh, người mệt, ngại nói chuyện."},{"question":"Có khát nước không? Thích uống nóng hay lạnh?","response":"Không khát, chỉ thích uống nước ấm."},{"question":"Đã dùng thuốc gì? Đã nội soi lần nào chưa?","response":"Chưa nội soi lần nào. Thỉnh thoảng uống ibuprofen khi đau."},{"question":"Giấc ngủ và ăn uống gần đây?","response":"Ngủ được, ăn kém, hay đầy bụng sau ăn."},{"question":"Có uống rượu, hút thuốc không?","response":"Không uống rượu, không hút thuốc."},{"question":"Kinh nguyệt?","response":"Mãn kinh được 2 năm."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt vàng nhợt, tinh thần mệt mỏi, thể trạng gầy."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, bệu, có hằn răng, rêu trắng mỏng ướt."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói nhỏ, yếu. Hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch trầm, trì, nhược."},{"group":"T","item":"Sờ tay chân","finding":"Bàn tay, bàn chân lạnh."},{"group":"K","item":"Khám bụng","finding":"Thượng vị ấn đau nhẹ, bệnh nhân thích ấn. Bụng mềm, không phản ứng thành bụng."},{"group":"K","item":"Khám tim phổi","finding":"Không có dấu hiệu bất thường."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 12,1 g/dL, bạch cầu bình thường."},{"name":"Nội soi dạ dày","duration_minutes":20,"result":"Loét hang vị nhỏ 0,5 cm, đáy sạch, bờ đều, không nghi ngờ ác tính."},{"name":"Test urease / hơi thở tìm H. pylori","duration_minutes":15,"result":"Dương tính."},{"name":"CT ngực bụng có cản quang","duration_minutes":40,"result":"Không thấy bất thường. Không có chỉ định ở ca này."},{"name":"Điện tâm đồ","duration_minutes":3,"result":"Nhịp xoang, không bất thường."}],"choices":{"diagnosis":{"ydx":["Ung thư dạ dày","Loét dạ dày có nhiễm H. pylori","Viêm tụy cấp","Hội chứng ruột kích thích"],"bd":["Vị quản thống","Phúc thống","Tiết tả","Hung tý"],"bc":["Lý – Hư – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Hàn","Lý – Thực – Nhiệt"],"the":["Tỳ vị hư hàn","Can khí phạm vị","Vị âm hư","Thực tích đình trệ","Huyết ứ trở lạc"],"phap":["Ôn trung kiện tỳ, hòa hoãn chỉ thống","Thanh nhiệt tả hỏa","Sơ can lý khí","Hoạt huyết hóa ứ","Dưỡng âm ích vị"],"phuong":["Hoàng kỳ kiến trung thang","Ích vị thang","Sài hồ sơ can tán","Lý trung hoàn","Bạch hổ thang"],"huyet":["Túc tam lý","Phong trì","Thái xung","Đại chùy","Nội quan","Hợp cốc","Vị du","Tỳ du","Trung quản"]},"actions":["Cho thuốc thanh nhiệt hàn lương (Hoàng liên, Thạch cao)","Truyền kháng sinh phổ rộng đường tĩnh mạch","Cứu ngải vùng Trung quản, Quan nguyên","Dặn ngừng thuốc kháng viêm giảm đau (NSAID)","Điều trị diệt H. pylori theo phác đồ YHHĐ","Hướng dẫn ăn chín, ấm, chia nhỏ bữa","Hẹn tái khám, nội soi kiểm tra sau điều trị"]}}'::jsonb,
  '93032b4ce031c3cc62fd164db2fb74e9e0021b78a2d083be56031fbb4af51d8f'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'vi-quan-thong',
  '{"schema_version":"1.0.0","case_id":"vi-quan-thong","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-hp-acg-2024-9052a89c3452","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/39626064/","title":"American College of Gastroenterology, ACG Clinical Guideline: Treatment of Helicobacter pylori Infection, 2024.","organization":null,"year_version":null,"citation":"American College of Gastroenterology, ACG Clinical Guideline: Treatment of Helicobacter pylori Infection, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,7],"examination_essential_indices":[0,1,3,5],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"waste"},{"index":4,"role":"neutral"}],"diagnosis_options":{"ydx":[{"text":"Loét dạ dày có nhiễm H. pylori","credit":"full"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Ung thư dạ dày","credit":"none"},{"text":"Viêm tụy cấp","credit":"none"}],"bd":[{"text":"Vị quản thống","credit":"full"},{"text":"Hung tý","credit":"none"},{"text":"Phúc thống","credit":"none"},{"text":"Tiết tả","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Tỳ vị hư hàn","credit":"full"},{"text":"Can khí phạm vị","credit":"none"},{"text":"Vị âm hư","credit":"none"},{"text":"Thực tích đình trệ","credit":"none"},{"text":"Huyết ứ trở lạc","credit":"none"}],"phap":[{"text":"Ôn trung kiện tỳ, hòa hoãn chỉ thống","credit":"full"},{"text":"Sơ can lý khí","credit":"none"},{"text":"Thanh nhiệt tả hỏa","credit":"none"},{"text":"Hoạt huyết hóa ứ","credit":"none"},{"text":"Dưỡng âm ích vị","credit":"none"}],"phuong":[{"text":"Hoàng kỳ kiến trung thang","credit":"full"},{"text":"Lý trung hoàn","credit":"full"},{"text":"Sài hồ sơ can tán","credit":"none"},{"text":"Ích vị thang","credit":"none"},{"text":"Bạch hổ thang","credit":"none"}],"huyet":[{"text":"Trung quản","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Vị du","credit":"full"},{"text":"Nội quan","credit":"full"},{"text":"Thái xung","credit":"none"},{"text":"Hợp cốc","credit":"none"},{"text":"Đại chùy","credit":"none"},{"text":"Phong trì","credit":"none"}]},"action_options":[{"text":"Hướng dẫn ăn chín, ấm, chia nhỏ bữa","time_minutes":2,"grade":"recommended","rationale":"Chế độ ăn hợp với tỳ vị hư hàn."},{"text":"Dặn ngừng thuốc kháng viêm giảm đau (NSAID)","time_minutes":1,"grade":"recommended","rationale":"NSAID làm loét nặng thêm."},{"text":"Điều trị diệt H. pylori theo phác đồ YHHĐ","time_minutes":2,"grade":"recommended","rationale":"Loét có H. pylori cần diệt khuẩn."},{"text":"Cứu ngải vùng Trung quản, Quan nguyên","time_minutes":10,"grade":"recommended","rationale":"Ôn dương, tán hàn."},{"text":"Hẹn tái khám, nội soi kiểm tra sau điều trị","time_minutes":1,"grade":"recommended","rationale":"Theo dõi liền sẹo loét."},{"text":"Cho thuốc thanh nhiệt hàn lương (Hoàng liên, Thạch cao)","time_minutes":2,"grade":"harmful","rationale":"Thuốc hàn lương làm tổn thương thêm dương khí của tỳ vị."},{"text":"Truyền kháng sinh phổ rộng đường tĩnh mạch","time_minutes":3,"grade":"harmful","rationale":"Không có chỉ định, không phải nhiễm khuẩn toàn thân."}],"teaching_explanation":"Điểm mấu chốt: đau thích ấn, thích ấm, sợ lạnh, lưỡi nhạt bệu rêu trắng, mạch trầm trì nhược cho ra thể Tỳ vị hư hàn. Cần loại trừ dấu hiệu báo động (sụt cân, phân đen, nuốt nghẹn) và xác nhận nguyên nhân bằng nội soi, H. pylori. Thuốc hàn lương là bẫy thường gặp."}'::jsonb,
  'eee19d6859acfcde1e62ce3dd9998c5e27a8f7082ac897379ad86647ea68a77b'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
