values (
  'tiet-ta',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"tiet-ta","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tiêu chảy nước 8 lần sau gỏi hải sản","setting":"capcuu","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Chị Hồ Thị Thu"},"presentation":{"intro":"Phòng cấp cứu, 08:30. Chị tiêu chảy 8 lần từ đêm qua, đau quặn bụng, chóng mặt khi đứng dậy. Người ăn cùng cũng bị.","place":"Phòng cấp cứu","clock":"08:30","night":false},"vitals":{"hr":104,"sbp":100,"dbp":65,"rr":20,"temperature_c":37.8,"spo2":98},"history":[{"question":"Phân thế nào, mấy lần, có máu hay nhầy không?","response":"Phân lỏng như nước, vàng, mùi thối khắm, không máu, không nhầy. 8 lần từ đêm qua."},{"question":"Có đau quặn bụng, mót rặn không?","response":"Đau quặn quanh rốn, không mót rặn."},{"question":"Hôm qua ăn gì? Người cùng ăn có bị không?","response":"Ăn gỏi hải sản, nem chua. Hai người cùng ăn cũng bị tiêu chảy."},{"question":"Có nôn, sốt không?","response":"Nôn 2 lần, sốt nhẹ."},{"question":"Nước tiểu, khát nước?","response":"Nước tiểu ít, sẫm màu. Khát nhiều, thích uống mát."},{"question":"Có chóng mặt, ngất khi đứng dậy không?","response":"Chóng mặt khi đứng, chưa ngất."}],"examination":[{"group":"K","item":"Dấu mất nước","finding":"Môi khô, mắt hơi trũng, véo da mất chậm."},{"group":"K","item":"Khám bụng","finding":"Ấn đau lan tỏa nhẹ, nhu động ruột tăng, không có phản ứng thành bụng."},{"group":"K","item":"Mạch","finding":"Mạch nhanh."},{"group":"K","item":"Mùi phân","finding":"Mùi thối khắm."}],"investigations":[{"name":"Điện giải đồ","duration_minutes":10,"result":"Na 134, K 3,3 mmol/L."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bạch cầu 11.000, CRP hơi tăng."},{"name":"Soi phân, cấy phân","duration_minutes":15,"result":"Hồng cầu không có, bạch cầu ít. Cấy phân có kết quả sau 48 giờ."},{"name":"CT bụng","duration_minutes":30,"result":"Không có chỉ định."}],"choices":{"diagnosis":{"ydx":["Tả","Viêm đại tràng giả mạc","Tiêu chảy cấp nhiễm khuẩn, mất nước mức vừa","Viêm ruột thừa","Hội chứng ruột kích thích"]},"actions":["Kháng sinh nhóm quinolon cho mọi ca tiêu chảy","Nhịn ăn, nhịn uống 24 giờ","Đánh giá mức độ mất nước, đo mạch huyết áp lặp lại","Ăn cháo loãng, tiếp tục ăn sớm khi dung nạp","Bù dịch ORS đường uống, hoặc Ringer lactat tĩnh mạch nếu không uống được","Theo dõi nước tiểu, bù kali theo điện giải","Cho thuốc cầm tiêu chảy mạnh (loperamid) khi có sốt"]}}'::jsonb,
  '1bf81daaf1fc6b5ec6fe6b6b7e729003f5263fd923a4284bd5945dc63d8a215d'
)
