values (
  'tiet-ta',
  '{"schema_version":"1.0.0","case_id":"tiet-ta","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-diarrhea-idsa-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29053792/","title":"Infectious Diseases Society of America, Clinical Practice Guidelines for the Diagnosis and Management of Infectious Diarrhea, 2017.","organization":null,"year_version":null,"citation":"Infectious Diseases Society of America, Clinical Practice Guidelines for the Diagnosis and Management of Infectious Diarrhea, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,2,4,5],"examination_essential_indices":[0,1,2],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Tiêu chảy cấp nhiễm khuẩn, mất nước mức vừa","credit":"full"},{"text":"Viêm đại tràng giả mạc","credit":"none"},{"text":"Hội chứng ruột kích thích","credit":"none"},{"text":"Viêm ruột thừa","credit":"none"},{"text":"Tả","credit":"none"}]},"action_options":[{"text":"Đánh giá mức độ mất nước, đo mạch huyết áp lặp lại","time_minutes":1,"grade":"critical","rationale":"Quyết định đường bù dịch."},{"text":"Bù dịch ORS đường uống, hoặc Ringer lactat tĩnh mạch nếu không uống được","time_minutes":2,"grade":"critical","rationale":"Bù dịch là điều trị quan trọng nhất."},{"text":"Theo dõi nước tiểu, bù kali theo điện giải","time_minutes":2,"grade":"recommended","rationale":"Kali 3,3 cần theo dõi và bù."},{"text":"Ăn cháo loãng, tiếp tục ăn sớm khi dung nạp","time_minutes":2,"grade":"recommended","rationale":"Phục hồi niêm mạc ruột."},{"text":"Kháng sinh nhóm quinolon cho mọi ca tiêu chảy","time_minutes":2,"grade":"waste","rationale":"Phần lớn tiêu chảy cấp không cần kháng sinh."},{"text":"Cho thuốc cầm tiêu chảy mạnh (loperamid) khi có sốt","time_minutes":1,"grade":"harmful","rationale":"Có thể giữ độc tố, nguy cơ biến chứng ở tiêu chảy nhiễm khuẩn có sốt."},{"text":"Nhịn ăn, nhịn uống 24 giờ","time_minutes":1,"grade":"harmful","rationale":"Làm mất nước nặng thêm."}],"teaching_explanation":"Tiêu chảy cấp xử trí đầu tiên là bù dịch. Cầm tiêu chảy mạnh khi có sốt có thể có hại, kháng sinh không dùng thường quy."}'::jsonb,
