  '{"schema_version":"1.0.0","case_id":"huyen-vung","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Chóng mặt đau đầu, huyết áp 168/102","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nữ","patient_label":"Bà Trương Thị Lan"},"presentation":{"intro":"Khoa Nội, giường 8. Bà kể mấy ngày nay chóng mặt, đau đầu vùng thái dương, hay cáu gắt, ngủ kém.","place":"Khoa Nội, giường 8","clock":"10:00","night":false},"vitals":{"hr":84,"sbp":168,"dbp":102,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Chóng mặt, đau đầu thế nào, khi nào nặng thêm?","response":"Chóng mặt, đau đầu thái dương, nặng thêm khi tức giận hoặc thiếu ngủ."},{"question":"Có yếu liệt, nói khó, nhìn đôi, đau ngực, khó thở không?","response":"Không có."},{"question":"Tiền sử tăng huyết áp, dùng thuốc thế nào?","response":"Tăng huyết áp 8 năm, uống amlodipin nhưng hay quên."},{"question":"Có nóng nảy, miệng đắng, mắt đỏ không?","response":"Hay cáu, miệng đắng, mắt đỏ."},{"question":"Giấc ngủ, đại tiểu tiện?","response":"Mất ngủ, hay mơ. Táo bón, tiểu vàng."},{"question":"Ăn mặn, rượu, hút thuốc?","response":"Ăn mặn, không rượu, không hút thuốc."},{"question":"Kinh nguyệt?","response":"Mãn kinh 6 năm."}],"examination":[{"group":"K","item":"Đo huyết áp đúng kỹ thuật, hai tay","finding":"Hai tay 168/102 và 166/100."},{"group":"K","item":"Khám thần kinh","finding":" Dây thần kinh sọ bình thường."},{"group":"K","item":"Khám tim phổi","finding":"Tim đều, phổi bình thường."},{"group":"K","item":"Sắc mặt, mắt","finding":"Mặt đỏ, mắt đỏ."},{"group":"K","item":"Mạch","finding":"Mạch đều."}],"investigations":[{"name":"Điện tâm đồ","duration_minutes":3,"result":"Dày thất trái nhẹ."},{"name":"Điện giải, creatinin, đường huyết, lipid máu","duration_minutes":10,"result":"Cholesterol toàn phần 6,2 mmol/L. Chức năng thận bình thường."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Chưa có đạm niệu."},{"name":"CT sọ não","duration_minutes":20,"result":"Không có chỉ định khi không có dấu thần kinh khu trú."}],"choices":{"diagnosis":{"ydx":["Tăng huyết áp độ 2 chưa kiểm soát, không có tổn thương cơ quan đích cấp","Chóng mặt tư thế kịch phát lành tính","Thiếu máu","Đột quỵ thiếu máu não","Cấp cứu tăng huyết áp"]},"actions":["Ngậm nifedipine dưới lưỡi để hạ áp nhanh","Giảm muối, ngủ đủ, giữ tinh thần thư thái","Nhập viện cấp cứu truyền thuốc hạ áp","Chụp CT sọ ngay","Đo lại huyết áp ngồi nghỉ 5 phút, ghi nhật ký huyết áp tại nhà","Điều chỉnh thuốc hạ áp YHHĐ, dặn uống đều mỗi ngày"]}}'::jsonb,
