values (
  'yeu-thong',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"yeu-thong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thắt lưng sau dầm mưa","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":38,"sex":"nam","patient_label":"Anh Phạm Văn Tuấn"},"presentation":{"intro":"Khoa Châm cứu, giường 5. Anh là thợ xây, đau thắt lưng 3 ngày sau khi làm việc dưới mưa lạnh.","place":"Phòng châm cứu","clock":"14:00","night":false},"vitals":{"hr":76,"sbp":125,"dbp":80,"rr":16,"temperature_c":36.7,"spo2":99},"history":[{"question":"Đau từ khi nào, sau việc gì?","response":"Đau 3 ngày, sau buổi làm việc dưới mưa. Tuần trước có bê vật nặng."},{"question":"Tính chất đau, chườm ấm hay trời lạnh thì sao?","response":"Đau nặng, lạnh, cứng. Trời lạnh ẩm đau tăng, chườm ấm đỡ."},{"question":"Có lan xuống chân, tê hay yếu chân không?","response":"Không lan, không tê, không yếu chân."},{"question":"Có rối loạn tiểu tiện hoặc tê vùng yên ngựa không?","response":"Không."},{"question":"Có sốt, sụt cân, đau đêm không đỡ không?","response":"Không sốt, không sụt cân. Đau giảm khi nằm nghỉ."},{"question":"Ăn ngủ, đại tiểu tiện?","response":"Ăn ngủ bình thường, đại tiểu tiện bình thường."}],"examination":[{"group":"K","item":"Dáng đi, tầm vận động","finding":"Dáng đi cứng, nghiêng nhẹ. Cúi và ngả lưng hạn chế vì đau."},{"group":"K","item":"Sờ nắn cột sống thắt lưng","finding":"Co cứng cơ cạnh sống hai bên, ấn đau vùng L4–L5. Không có điểm đau chói gai sống."},{"group":"K","item":"Lasègue, phản xạ, lực cơ","finding":"Lasègue âm tính. Phản xạ gân xương bình thường. Lực cơ 5/5."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng nhớt."},{"group":"T","item":"Mạch","finding":"Mạch trầm, khẩn."},{"group":"T","item":"Sờ vùng thắt lưng","finding":"Vùng thắt lưng lạnh, sờ vào cơ căng cứng."}],"investigations":[{"name":"X-quang cột sống thắt lưng","duration_minutes":10,"result":"Thoái hóa nhẹ. Không gãy, không trượt đốt sống."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Trong giới hạn bình thường."},{"name":"MRI cột sống thắt lưng","duration_minutes":40,"result":"Không có chỉ định ở đợt đau cấp đầu tiên khi chưa có dấu hiệu báo động."}],"choices":{"diagnosis":{"ydx":["Hội chứng đuôi ngựa","Đau thắt lưng cấp do co cứng cơ (không đặc hiệu)","Viêm cột sống dính khớp","Thoát vị đĩa đệm chèn ép rễ","Sỏi thận"],"bd":["Hành tý","Yêu thống","Nuy chứng","Lâm chứng"],"bc":["Biểu – Hư","Lý – Hư – Hàn","Thực – Hàn (bệnh ở kinh lạc, cơ nhục)","Lý – Thực – Nhiệt"],"the":["Thận hư yêu thống","Thấp nhiệt","Hàn thấp (phong hàn thấp) trở lạc","Huyết ứ"],"phap":["Tán hàn trừ thấp, ôn kinh thông lạc","Bổ thận cường yêu","Thanh nhiệt lợi thấp","Hoạt huyết hóa ứ"],"phuong":["Tứ diệu hoàn","Thân thống trục ứ thang","Can khương Linh truật thang (Thận trước thang)","Lục vị địa hoàng hoàn","Độc hoạt tang ký sinh thang"],"huyet":["A thị huyệt","Hợp cốc","Đại trường du","Thận du","Thái xung","Đản trung","Ủy trung","Nội quan","Yêu dương quan"]},"actions":["Giác hơi hoặc cứu ngải vùng thắt lưng","Hẹn chụp MRI để chắc chắn","Xoa bóp, day ấn huyệt nhẹ nhàng","Hướng dẫn giữ ấm, tránh mưa lạnh","Hướng dẫn vận động nhẹ, tránh bê vác nặng","Chỉ định phẫu thuật ngay","Thuốc giãn cơ hoặc giảm đau ngắn ngày nếu cần","Nắn chỉnh cột sống mạnh, xoay cưỡng bức","Nằm bất động tuyệt đối 2 tuần"]}}'::jsonb,
