values (
  'thong-phong',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"thong-phong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Sưng đỏ ngón chân cái sau tiệc","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":48,"sex":"nam","patient_label":"Ông Đỗ Văn Lợi"},"presentation":{"intro":"Phòng khám Nội, giường 3. Ông đi tập tễnh, kể nửa đêm đau dữ dội ngón chân cái bàn chân phải, đến sáng sưng đỏ.","place":"Phòng khám Nội","clock":"08:30","night":false},"vitals":{"hr":90,"sbp":140,"dbp":90,"rr":18,"temperature_c":37.9,"spo2":98},"history":[{"question":"Đau khớp nào, bắt đầu khi nào, đau thế nào?","response":"Ngón cái chân phải, nửa đêm đau dữ dội, không chịu nổi cả tấm drap chạm vào."},{"question":"Gần đây ăn uống gì?","response":"Dự tiệc hôm qua, uống nhiều bia, ăn hải sản, nội tạng."},{"question":"Tiền sử gút, bệnh thận, thuốc đang dùng?","response":"Một cơn tương tự cách đây một năm. Đang dùng hydrochlorothiazide trị huyết áp."},{"question":"Tiền sử loét dạ dày, dị ứng thuốc?","response":"Từng loét dạ dày 3 năm trước."},{"question":"Có sốt, khớp nào khác sưng không?","response":"Sốt nhẹ, chỉ đau một khớp."},{"question":"Tiểu tiện, đại tiện?","response":"Nước tiểu vàng sẫm, táo."},{"question":"Có chấn thương khớp gần đây không?","response":"Không."}],"examination":[{"group":"V","item":"Quan sát khớp","finding":"Khớp bàn ngón chân cái phải sưng, đỏ bóng, căng."},{"group":"K","item":"Sờ nắn khớp","finding":"Nóng, đau chói khi chạm, không hạn chế vận động các khớp khác."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng nhớt."},{"group":"T","item":"Mạch","finding":"Mạch hoạt, sác."},{"group":"V","item":"Thể trạng","finding":"Thể trạng béo, mặt đỏ."},{"group":"K","item":"Tìm hạt tophi, khám tim phổi","finding":"Không thấy hạt tophi. Tim phổi bình thường."}],"investigations":[{"name":"Acid uric máu","duration_minutes":10,"result":"520 µmol/L."},{"name":"Công thức máu, CRP","duration_minutes":10,"result":"Bạch cầu 12.500, CRP 48 mg/L."},{"name":"Creatinin, độ lọc cầu thận","duration_minutes":10,"result":"eGFR 78. Chức năng thận còn tốt."},{"name":"Chọc hút dịch khớp, soi tinh thể urat","duration_minutes":15,"result":"Tinh thể hình kim, lưỡng chiết âm tính."},{"name":"Cấy máu","duration_minutes":20,"result":"Chưa có kết quả, không trì hoãn điều trị."},{"name":"MRI khớp bàn chân","duration_minutes":40,"result":"Không có chỉ định ở cơn điển hình."}],"choices":{"diagnosis":{"ydx":["Cơn gút cấp (viêm khớp do tinh thể urat)","Viêm khớp nhiễm khuẩn","Giả gút","Chấn thương phần mềm","Viêm khớp dạng thấp"],"bd":["Lịch tiết phong","Thống phong","Nuy chứng","Hành tý"],"bc":["Lý – Hư – Nhiệt","Lý – Hư – Hàn","Lý – Thực – Nhiệt","Biểu – Thực – Hàn"],"the":["Đàm ứ tý trở","Thấp nhiệt uẩn kết","Phong hàn thấp tý","Can thận lưỡng hư"],"phap":["Hóa đàm hoạt huyết","Thanh nhiệt lợi thấp, thông lạc chỉ thống","Bổ ích can thận","Tán hàn trừ thấp"],"phuong":["Can khương Linh truật thang","Bạch hổ gia quế chi thang","Lục vị địa hoàng hoàn","Độc hoạt tang ký sinh thang","Tứ diệu hoàn gia giảm"],"huyet":["Thái xung","Khúc trì","Đại đô","Thái bạch","Mệnh môn","Quan nguyên","Thận du","Cao hoang","Âm lăng tuyền"]},"actions":["Châm thanh nhiệt, chích nặn máu nhẹ tại Đại đô, Thái xung","Uống nhiều nước, bỏ bia rượu, hải sản, nội tạng","Dùng colchicine liều thấp hoặc corticoid ngắn ngày","Bắt đầu thuốc hạ acid uric ngay giữa cơn mà không che chắn kháng viêm","Nghỉ ngơi, kê cao chân, chườm lạnh quanh khớp","Kháng sinh tĩnh mạch kéo dài","Rà soát thuốc lợi tiểu thiazid đang dùng với bác sĩ điều trị tăng huyết áp","Chườm nóng, cứu ngải trực tiếp tại khớp đang sưng nóng","Dùng kháng viêm không steroid liều cao (diclofenac)"]}}'::jsonb,
