,"credit":"full"},{"text":"Hành tý","credit":"none"},{"text":"Nuy chứng","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Thấp nhiệt uẩn kết","credit":"full"},{"text":"Phong hàn thấp tý","credit":"none"},{"text":"Đàm ứ tý trở","credit":"none"},{"text":"Can thận lưỡng hư","credit":"none"}],"phap":[{"text":"Thanh nhiệt lợi thấp, thông lạc chỉ thống","credit":"full"},{"text":"Tán hàn trừ thấp","credit":"none"},{"text":"Bổ ích can thận","credit":"none"},{"text":"Hóa đàm hoạt huyết","credit":"none"}],"phuong":[{"text":"Tứ diệu hoàn gia giảm","credit":"full"},{"text":"Bạch hổ gia quế chi thang","credit":"partial"},{"text":"Độc hoạt tang ký sinh thang","credit":"none"},{"text":"Can khương Linh truật thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"}],"huyet":[{"text":"Đại đô","credit":"full"},{"text":"Thái bạch","credit":"full"},{"text":"Âm lăng tuyền","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Khúc trì","credit":"full"},{"text":"Quan nguyên","credit":"none"},{"text":"Mệnh môn","credit":"none"},{"text":"Thận du","credit":"none"},{"text":"Cao hoang","credit":"none"}]},"action_options":[{"text":"Dùng colchicine liều thấp hoặc corticoid ngắn ngày","time_minutes":1,"grade":"recommended","rationale":"Ưu tiên vì tiền sử loét dạ dày, tránh kháng viêm không steroid."},{"text":"Nghỉ ngơi, kê cao chân, chườm lạnh quanh khớp","time_minutes":2,"grade":"recommended","rationale":"Giảm sưng đau."},{"text":"Uống nhiều nước, bỏ bia rượu, hải sản, nội tạng","time_minutes":2,"grade":"recommended","rationale":"Giảm acid uric, tránh cơn tái phát."},{"text":"Rà soát thuốc lợi tiểu thiazid đang dùng với bác sĩ điều trị tăng huyết áp","time_minutes":2,"grade":"recommended","rationale":"Thiazid làm tăng acid uric."},{"text":"Châm thanh nhiệt, chích nặn máu nhẹ tại Đại đô, Thái xung","time_minutes":5,"grade":"recommended","rationale":"Hỗ trợ giảm sưng nóng, không thay thuốc cắt cơn."},{"text":"Bắt đầu thuốc hạ acid uric ngay giữa cơn mà không che chắn kháng viêm","time_minutes":1,"grade":"waste","rationale":"Nên cắt cơn trước, thuốc hạ acid uric bắt đầu sau khi dịu và có dự phòng cơn."},{"text":"Kháng sinh tĩnh mạch kéo dài","time_minutes":3,"grade":"waste","rationale":"Chưa có bằng chứng nhiễm khuẩn khớp."},{"text":"Dùng kháng viêm không steroid liều cao (diclofenac)","time_minutes":1,"grade":"harmful","rationale":"Có tiền sử loét dạ dày, nguy cơ chảy máu tiêu hóa."},{"text":"Chườm nóng, cứu ngải trực tiếp tại khớp đang sưng nóng","time_minutes":3,"grade":"harmful","rationale":"Làm nhiệt tăng thêm, sai thể thấp nhiệt."}],"teaching_explanation":"Cơn gút cấp cắt cơn trước, hạ acid uric sau. Hỏi tiền sử loét dạ dày và thuốc lợi tiểu thiazid thay đổi lựa chọn thuốc. Thể thấp nhiệt khác phong hàn thấp: sưng nóng đỏ, lưỡi đỏ rêu vàng nhớt, mạch hoạt sác, kỵ cứu nóng. Sốt nhẹ một khớp luôn cần nghĩ đến viêm khớp nhiễm khuẩn."}'::jsonb,
  '3e14d2072520f66053bb1d108020a6ef4f71c146b634eb99d23a88e00b92761a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

