values (
  'truong-ung',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"truong-ung","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng từ quanh rốn xuống hố chậu phải","setting":"capcuu","level":"Trung bình","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":22,"sex":"nam","patient_label":"Anh Lê Hoàng Phúc"},"presentation":{"intro":"Phòng cấp cứu, 15:00. Anh đau bụng 14 giờ, ban đầu quanh rốn, sau chuyển xuống hố chậu phải, chán ăn, nôn.","place":"Phòng cấp cứu","clock":"15:00","night":false},"vitals":{"hr":100,"sbp":118,"dbp":74,"rr":18,"temperature_c":38.2,"spo2":99},"history":[{"question":"Đau bắt đầu ở đâu, có di chuyển không?","response":"Bắt đầu quanh rốn, sau 6 đến 8 giờ chuyển xuống hố chậu phải, đau tăng khi đi lại hoặc ho."},{"question":"Có chán ăn, buồn nôn, nôn không?","response":"Chán ăn, nôn 2 lần."},{"question":"Có sốt không?","response":"Sốt khoảng 38 độ."},{"question":"Đại tiện, tiểu tiện thế nào?","response":"Táo nhẹ, không tiêu chảy. Tiểu bình thường, không buốt."},{"question":"Tiền sử bệnh, phẫu thuật bụng?","response":"Không có."},{"question":"Đã dùng thuốc gì?","response":"Uống 1 viên paracetamol, đỡ ít."}],"examination":[{"group":"K","item":"Ấn bụng hố chậu phải","finding":"Đau điểm McBurney, phản ứng thành bụng khu trú."},{"group":"K","item":"Các dấu hiệu viêm ruột thừa","finding":"Blumberg dương tính, Rovsing dương tính."},{"group":"K","item":"Co cứng thành bụng lan tỏa?","finding":"Không có, chưa có dấu viêm phúc mạc lan tỏa."},{"group":"K","item":"Mạch","finding":"Mạch nhanh."},{"group":"K","item":"Hơi thở, phân","finding":"Hơi thở hôi, đại tiện táo."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 15.800, trung tính 85%."},{"name":"CRP","duration_minutes":10,"result":"62 mg/L."},{"name":"Siêu âm bụng","duration_minutes":10,"result":"Ruột thừa 9 mm, thành dày, không xẹp, có dịch quanh. Chưa thấy áp xe."},{"name":"CT bụng","duration_minutes":30,"result":"Xác nhận viêm ruột thừa, chưa có áp xe hay thủng."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bình thường."},{"name":"Chụp đại tràng cản quang","duration_minutes":30,"result":"Không có chỉ định, có thể nguy hiểm khi nghi viêm ruột thừa."}],"choices":{"diagnosis":{"ydx":["Viêm ruột thừa cấp (chưa biến chứng)","Viêm túi thừa Meckel","Sỏi niệu quản phải","Viêm dạ dày ruột","Viêm hạch mạc treo"]},"actions":["Nhịn ăn uống, lập đường truyền, giảm đau theo y lệnh","Cho thuốc nhuận tràng, thuốc xổ","Kháng sinh tĩnh mạch theo phác đồ trước mổ","Chườm nóng lên bụng","Hội chẩn ngoại khoa, chuẩn bị cắt ruột thừa"]}}'::jsonb,
  'dbe3ed5ce4058b5571793af1c39b236e0b20fd980d9074fd9f37b14837909a24'
)
