values (
  'truong-ung',
  '{"schema_version":"1.0.0","case_id":"truong-ung","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-appendicitis-wses-2025","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/41604201/","title":"WSES, Diagnosis and Treatment of Acute Appendicitis: 2025 Edition of the WSES Jerusalem Guidelines, công bố năm 2026.","organization":null,"year_version":null,"citation":"WSES, Diagnosis and Treatment of Acute Appendicitis: 2025 Edition of the WSES Jerusalem Guidelines, công bố năm 2026.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,3],"examination_essential_indices":[0,1,2,3],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm ruột thừa cấp (chưa biến chứng)","credit":"full"},{"text":"Sỏi niệu quản phải","credit":"none"},{"text":"Viêm hạch mạc treo","credit":"none"},{"text":"Viêm dạ dày ruột","credit":"none"},{"text":"Viêm túi thừa Meckel","credit":"none"}]},"action_options":[{"text":"Nhịn ăn uống, lập đường truyền, giảm đau theo y lệnh","time_minutes":2,"grade":"critical","rationale":"Chuẩn bị phẫu thuật, giữ ổn định."},{"text":"Hội chẩn ngoại khoa, chuẩn bị cắt ruột thừa","time_minutes":3,"grade":"critical","rationale":"Viêm ruột thừa cấp có chỉ định can thiệp sớm."},{"text":"Kháng sinh tĩnh mạch theo phác đồ trước mổ","time_minutes":2,"grade":"recommended","rationale":"Giảm nhiễm khuẩn quanh mổ."},{"text":"Cho thuốc nhuận tràng, thuốc xổ","time_minutes":2,"grade":"harmful","rationale":"Làm tăng nguy cơ thủng ruột thừa."},{"text":"Chườm nóng lên bụng","time_minutes":2,"grade":"harmful","rationale":"Làm viêm tiến triển nhanh."}],"teaching_explanation":"Viêm ruột thừa cấp điển hình là chỉ định ngoại khoa. Bác sĩ trực phải nhận ra ca cần mổ và hội chẩn ngoại khoa sớm, không trì hoãn bằng điều trị khác."}'::jsonb,
