values (
  'soc-phan-ve-thuoc',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"soc-phan-ve-thuoc","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nổi mẩn, khó thở sau tiêm thuốc","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Chị Lê Thị Hoa"},"presentation":{"intro":"Phòng tiêm của trạm y tế đưa chị vào lúc 15:40. Mười phút trước chị được tiêm kháng sinh do viêm họng, sau đó nổi mẩn khắp người, khó thở, chóng mặt, suýt ngất.","place":"Phòng cấp cứu","clock":"15:40","night":false},"vitals":{"hr":128,"sbp":70,"dbp":40,"rr":28,"temperature_c":36.8,"spo2":88},"history":[{"question":"Chị tiêm thuốc gì, cách đây bao lâu?","response":"Thuốc kháng sinh tiêm bắp, khoảng 10 phút trước."},{"question":"Triệu chứng bắt đầu thế nào?","response":"Ngứa khắp người, nổi mẩn, tức ngực, thở rít, chóng mặt."},{"question":"Trước đây có dị ứng thuốc hay thức ăn không?","response":"Chưa biết dị ứng thuốc nào, hay nổi mề đay khi ăn hải sản."},{"question":"Có đau bụng, buồn nôn, tiêu chảy không?","response":"Có đau quặn bụng và buồn nôn."},{"question":"Có tiền sử hen, bệnh tim không?","response":"Không hen, không bệnh tim."},{"question":"Đang dùng thuốc gì khác?","response":"Không dùng thuốc nào khác."},{"question":"Có mang thai không?","response":"Không, vừa hết kinh tuần trước."},{"question":"Ăn uống gần đây có gì lạ không?","response":"Trưa ăn cơm bình thường."}],"examination":[{"group":"K","item":"Nhìn da mặt, toàn thân","finding":"Mày đay lan khắp thân, mặt phù nề, môi sưng, da lạnh vã mồ hôi"},{"group":"K","item":"Tri giác","finding":"Li bì, trả lời chậm"},{"group":"K","item":"Nghe phổi, tiếng thở","finding":"Thở rít thanh quản, ran rít hai phế trường"},{"group":"K","item":"Nghe tim","finding":"Tim nhanh đều, không tiếng thổi"},{"group":"K","item":"Mạch quay","finding":"Nhanh, nhỏ, khó bắt."},{"group":"K","item":"Sờ chi, đo huyết áp","finding":"Tay chân lạnh, huyết áp 70/40"},{"group":"K","item":"Khám bụng","finding":"Mềm, ấn đau nhẹ quanh rốn, không phản ứng thành bụng"}],"investigations":[{"name":"Điện tim","duration_minutes":3,"result":"Nhịp nhanh xoang, không thay đổi ST"},{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"6,1 mmol/L"},{"name":"Khí máu động mạch","duration_minutes":10,"result":"pH 7,31, PaO2 58 mmHg, lactate tăng nhẹ"},{"name":"Tryptase huyết thanh (lấy máu 1 đến 2 giờ sau khởi phát)","duration_minutes":5,"result":"Gửi mẫu, có kết quả sau"},{"name":"Chụp CT sọ não","duration_minutes":30,"result":"Không bất thường"},{"name":"Siêu âm bụng","duration_minutes":15,"result":"Không có gì đặc biệt"}],"choices":{"diagnosis":{"ydx":["Hội chứng mạch vành cấp","Sốc nhiễm khuẩn","Ngất do cường phế vị","Hen phế quản cấp","Sốc phản vệ độ 3 do thuốc"]},"actions":["Thở oxy lưu lượng cao qua mask","Chỉ cho kháng histamin uống rồi theo dõi","Gọi chụp CT sọ não","Dùng thêm kháng histamin và corticoid sau adrenalin","Ngừng thuốc nghi gây dị ứng và đặt tư thế phù hợp với biểu hiện","Tiêm bắp adrenalin vào mặt ngoài đùi theo liều phản vệ","Giữ theo dõi ít nhất 24 giờ","Theo dõi sát mạch, huyết áp, SpO2 liên tục","Cho bệnh nhân ngồi dậy đi lại","Đặt đường truyền, bù dịch muối đẳng trương nhanh"]}}'::jsonb,
  '86ba4632388509a023bbcb555514d5f241b68dcf551728cdc0df794974804e7e'
)
