  'soc-phan-ve-thuoc',
  '{"schema_version":"1.0.0","case_id":"soc-phan-ve-thuoc","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-byt-tt51-2017","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/thong-tu-51-2017-tt-byt-bo-y-te-158294-d1.html","title":"Bộ Y tế, Thông tư 51/2017/TT-BYT hướng dẫn phòng, chẩn đoán và xử trí phản vệ, 2017.","organization":null,"year_version":null,"citation":"Bộ Y tế, Thông tư 51/2017/TT-BYT hướng dẫn phòng, chẩn đoán và xử trí phản vệ, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-anaphylaxis-wao-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/33204386/","title":"World Allergy Organization, Anaphylaxis Guidance, 2020.","organization":null,"year_version":null,"citation":"World Allergy Organization, Anaphylaxis Guidance, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,1,2,4,5],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"neutral"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Sốc phản vệ độ 3 do thuốc","credit":"full"},{"text":"Hen phế quản cấp","credit":"none"},{"text":"Hội chứng mạch vành cấp","credit":"none"},{"text":"Ngất do cường phế vị","credit":"none"},{"text":"Sốc nhiễm khuẩn","credit":"none"}]},"action_options":[{"text":"Ngừng thuốc nghi gây dị ứng và đặt tư thế phù hợp với biểu hiện","time_minutes":1,"grade":"critical","rationale":"Tránh để người bệnh đột ngột đứng/ngồi. Thường nằm ngửa; nếu khó thở rõ có thể chọn tư thế dễ thở phù hợp, đồng thời ưu tiên hồi sức tuần hoàn."},{"text":"Tiêm bắp adrenalin vào mặt ngoài đùi theo liều phản vệ","time_minutes":2,"grade":"critical","rationale":"Thuốc đầu tay, tiêm sớm nhất"},{"text":"Thở oxy lưu lượng cao qua mask","time_minutes":1,"grade":"critical","rationale":"SpO2 88 phần trăm"},{"text":"Đặt đường truyền, bù dịch muối đẳng trương nhanh","time_minutes":3,"grade":"critical","rationale":"Huyết áp 70/40"},{"text":"Theo dõi sát mạch, huyết áp, SpO2 liên tục","time_minutes":1,"grade":"recommended","rationale":"Phát hiện tái diễn"},{"text":"Dùng thêm kháng histamin và corticoid sau adrenalin","time_minutes":3,"grade":"recommended","rationale":"Thuốc hỗ trợ, không thay thế adrenalin"},{"text":"Giữ theo dõi ít nhất 24 giờ","time_minutes":1,"grade":"recommended","rationale":"Phản vệ pha 2"},{"text":"Gọi chụp CT sọ não","time_minutes":30,"grade":"waste","rationale":"Không có chỉ định"},{"text":"Chỉ cho kháng histamin uống rồi theo dõi","time_minutes":3,"grade":"harmful","rationale":"Chậm trễ adrenalin có thể tử vong"},{"text":"Cho bệnh nhân ngồi dậy đi lại","time_minutes":1,"grade":"harmful","rationale":"Tụt huyết áp nặng thêm"}],"teaching_explanation":"Phản vệ nặng cần adrenalin tiêm bắp sớm, đánh giá ABC, oxy và bù dịch khi có sốc. Tư thế phải theo biểu hiện: tránh đứng/ngồi đột ngột; thường nằm ngửa, nhưng người khó thở có thể cần tư thế dễ thở phù hợp. Kháng histamin và corticoid chỉ hỗ trợ, không thay thế adrenalin."}'::jsonb,
  'cfc7cb0256150b38e99e99a6197251c7e6a9aeb016b1a66b229f4f0e44bf460a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'suy-tim-mat-bu-thuy-thung',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"suy-tim-mat-bu-thuy-thung","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Phù chân, khó thở khi nằm","setting":"giuong","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":72,"sex":"nữ","patient_label":"Bà Trần Thị Mai"},"presentation":{"intro":"Bà nhập viện hôm qua vì khó thở tăng dần, phù hai chân. Sáng nay bà phải ngồi dậy mới thở được, tiền sử tăng huyết áp nhiều năm, suy tim đã điều trị.","place":"Khoa Nội tim mạch","clock":"06:30","night":false},"vitals":{"hr":104,"sbp":118,"dbp":70,"rr":26,"temperature_c":36.9,"spo2":91},"history":[{"question":"Khó thở từ bao giờ, nằm có thở được không?","response":"Mấy ngày nay, nằm thì tức ngực khó thở, phải kê hai ba cái gối."},{"question":"Phù chân từ khi nào?","response":"Hơn một tuần, tăng dần cả hai chân."},{"question":"Có đau ngực, hồi hộp không?","response":"Hồi hộp nhiều, không đau thắt ngực."},{"question":"Tiểu tiện thế nào?","response":"Ít nước tiểu, đêm phải dậy."},{"question":"Bà có ăn mặn hoặc ngưng thuốc không?","response":"Mấy tuần nay ăn mặn và quên uống thuốc huyết áp."},{"question":"Có sốt, ho đờm không?","response":"Ho khan về đêm, không sốt."},{"question":"Sợ lạnh, tay chân lạnh không?","response":"Có, người lạnh, mệt mỏi, ăn kém."},{"question":"Bệnh nền khác?","response":"Tăng huyết áp 15 năm, chưa biết đái tháo đường."}],"examination":[{"group":"K","item":"Quan sát tư thế, cổ, phù","finding":"Ngồi đầu cao, tĩnh mạch cổ nổi, phù trũng hai chân đến gối"},{"group":"K","item":"Sắc mặt, môi","finding":"Mặt tái, môi tím nhẹ"},{"group":"K","item":"Nghe phổi","finding":"Ran ẩm hai đáy phổi"},{"group":"K","item":"Nghe tim","finding":"Tim nhanh, có tiếng ngựa phi T3"},{"group":"K","item":"Mạch","finding":"Nhanh, nhỏ, yếu."},{"group":"K","item":"Sờ gan, sờ chi","finding":"Gan to dưới bờ sườn 3 cm, ấn đau nhẹ, chân lạnh"},{"group":"K","item":"Cân nặng và nước tiểu","finding":"Tăng 3 kg trong 5 ngày, nước tiểu 400 ml mỗi ngày"}],"investigations":[{"name":"NT-proBNP","duration_minutes":30,"result":"Tăng cao"},{"name":"Điện tim","duration_minutes":3,"result":"Rung nhĩ đáp ứng thất nhanh nhẹ"},{"name":"X-quang ngực","duration_minutes":15,"result":"Bóng tim to, ứ huyết phổi, tràn dịch màng phổi ít"},{"name":"Siêu âm tim","duration_minutes":20,"result":"EF 35 phần trăm, giãn thất trái"},{"name":"Điện giải đồ, creatinin","duration_minutes":15,"result":"Natri 132, kali 3,7, creatinin hơi tăng"},{"name":"Nội soi dạ dày","duration_minutes":40,"result":"Không cần thiết lúc này"},{"name":"CT sọ não","duration_minutes":30,"result":"Không bất thường"}],"choices":{"diagnosis":{"ydx":["Suy tim mất bù, EF giảm","Viêm phổi cộng đồng","Hội chứng thận hư","Hen tim do thiếu máu","Thuyên tắc phổi"]},"actions":["Làm nội soi dạ dày","Cho ngồi đầu cao, thở oxy","Hạn chế muối và nước, cân và đo nước tiểu mỗi ngày","Tiêm lợi tiểu quai đường tĩnh mạch","Theo dõi điện giải, kali máu","Điều chỉnh thuốc suy tim, kiểm soát nhịp rung nhĩ","Kháng sinh phổ rộng thường quy","Cho bệnh nhân nằm ngửa bằng và hạn chế vận động tối thiểu","Truyền nhanh dịch muối đẳng trương 1000 ml"]}}'::jsonb,
  'c00ecbad1dbd8c3941cf861b3e67ec0d08905dd1051ea1512e4e79a44f9cedad'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

