values (
  'mat-ngu-tam-ty-luong-hu',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"mat-ngu-tam-ty-luong-hu","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Mất ngủ kéo dài, hay quên","setting":"phongkham","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":45,"sex":"nữ","patient_label":"Chị Nguyễn Thị Lan"},"presentation":{"intro":"Chị đi khám vì ba tháng nay ngủ khó, hay thức giấc, ban ngày mệt, hay quên, ăn kém. Chị là kế toán, áp lực cuối năm.","place":"Phòng khám Nội YHCT","clock":"09:15","night":false},"vitals":{"hr":84,"sbp":112,"dbp":70,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Ngủ như thế nào, khó vào giấc hay hay thức giấc?","response":"Khó vào giấc, ngủ chập chờn, mơ nhiều, thức dậy sớm."},{"question":"Hay hồi hộp, quên, mệt mỏi không?","response":"Hay quên, hồi hộp, sức khỏe sa sút."},{"question":"Ăn uống, tiêu hóa ra sao?","response":"Ăn kém, đầy bụng, đại tiện nhão."},{"question":"Kinh nguyệt thế nào?","response":"Kinh ít, màu nhạt, hơi trễ."},{"question":"Sụt cân, run tay, nóng bức không?","response":"Không."},{"question":"Có dùng cà phê, thuốc ngủ không?","response":"Một ly cà phê buổi sáng, chưa dùng thuốc ngủ."},{"question":"Có buồn bã, mất hứng thú kéo dài không?","response":"Thỉnh thoảng lo lắng, không buồn chán kéo dài."},{"question":"Có ngáy to, ngưng thở khi ngủ không?","response":"Chồng nói không ngáy."}],"examination":[{"group":"V","item":"Quan sát lưỡi","finding":"Lưỡi nhợt, rêu mỏng trắng"},{"group":"V","item":"Sắc mặt","finding":"Vàng úa, không tươi nhuận"},{"group":"M","item":"Tiếng nói, hơi thở","finding":"Nói nhỏ, ít hơi"},{"group":"T","item":"Mạch","finding":"Tế nhược"},{"group":"T","item":"Sờ bụng","finding":"Mềm, không đau"},{"group":"K","item":"Khám tuyến giáp","finding":"Không to"},{"group":"K","item":"Khám tim phổi","finding":"Bình thường"},{"group":"K","item":"Đo huyết áp, mạch","finding":"Mạch 84, huyết áp 112/70"}],"investigations":[{"name":"Công thức máu","duration_minutes":20,"result":"Hemoglobin 108 g/L, thiếu máu nhẹ"},{"name":"TSH","duration_minutes":30,"result":"Bình thường"},{"name":"Đường huyết","duration_minutes":5,"result":"Bình thường"},{"name":"Chụp MRI sọ não","duration_minutes":40,"result":"Không có chỉ định"},{"name":"Đa ký giấc ngủ","duration_minutes":120,"result":"Chưa cần ở bước này"}],"choices":{"diagnosis":{"ydx":["U não","Hội chứng ngưng thở khi ngủ","Cường giáp","Trầm cảm nặng","Mất ngủ mạn tính, nghi thiếu máu nhẹ"],"bd":["Kinh quý","Chính xung","Hư lao","Huyễn vựng","Bất mị"],"bc":["Lý hư hàn","Biểu hư hàn","Lý hư nhiệt","Biểu thực nhiệt","Lý thực nhiệt"],"the":["Tâm hỏa thượng viêm","Tâm tỳ lưỡng hư","Tâm thận bất giao","Đàm nhiệt nhiễu tâm","Can uất hóa hỏa"],"phap":["Thanh tâm tả hỏa","Tư âm giáng hỏa","Thanh hóa đàm nhiệt","Bổ ích tâm tỳ, dưỡng huyết an thần","Sơ can giải uất"],"phuong":["Ôn đởm thang","Long đởm tả can thang","Thiên vương bổ tâm đan","Quy tỳ thang","Hoàng liên a giao thang"],"huyet":["Tâm du","Hợp cốc","Thần môn","Tỳ du","Tam âm giao","Bách hội","Thiên đột","Phong long"]},"actions":["Hẹn tái khám sau 2 tuần, đánh giá lại giấc ngủ","Điều chỉnh chế độ ăn bổ huyết, điều trị thiếu máu nếu có","Kê benzodiazepin dài ngày ngay lần khám đầu","Kê Quy tỳ thang gia giảm","Tư vấn vệ sinh giấc ngủ, giảm cà phê buổi chiều","Châm hoặc cứu Thần môn, Tam âm giao","Chỉ định chụp MRI sọ não"]}}'::jsonb,
