values (
  'mat-ngu-tam-ty-luong-hu',
  '{"schema_version":"1.0.0","case_id":"mat-ngu-tam-ty-luong-hu","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-mat-ngu-tam-ty-luong-hu-1","resource_type":"other","source":"European Sleep Research Society và European Insomnia Network, The European Insomnia Guideline: An update on the diagnosis and treatment of insomnia, 2023.","title":"European Sleep Research Society và European Insomnia Network, The European Insomnia Guideline: An update on the diagnosis and treatment of insomnia, 2023.","organization":null,"year_version":null,"citation":"European Sleep Research Society và European Insomnia Network, The European Insomnia Guideline: An update on the diagnosis and treatment of insomnia, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,3,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Mất ngủ mạn tính, nghi thiếu máu nhẹ","credit":"full"},{"text":"Cường giáp","credit":"none"},{"text":"Trầm cảm nặng","credit":"none"},{"text":"Hội chứng ngưng thở khi ngủ","credit":"none"},{"text":"U não","credit":"none"}],"bd":[{"text":"Bất mị","credit":"full"},{"text":"Kinh quý","credit":"none"},{"text":"Chính xung","credit":"none"},{"text":"Hư lao","credit":"none"},{"text":"Huyễn vựng","credit":"none"}],"bc":[{"text":"Lý hư hàn","credit":"full"},{"text":"Biểu thực nhiệt","credit":"none"},{"text":"Lý thực nhiệt","credit":"none"},{"text":"Biểu hư hàn","credit":"none"},{"text":"Lý hư nhiệt","credit":"none"}],"the":[{"text":"Tâm tỳ lưỡng hư","credit":"full"},{"text":"Tâm hỏa thượng viêm","credit":"none"},{"text":"Can uất hóa hỏa","credit":"none"},{"text":"Tâm thận bất giao","credit":"none"},{"text":"Đàm nhiệt nhiễu tâm","credit":"none"}],"phap":[{"text":"Bổ ích tâm tỳ, dưỡng huyết an thần","credit":"full"},{"text":"Thanh tâm tả hỏa","credit":"none"},{"text":"Sơ can giải uất","credit":"none"},{"text":"Tư âm giáng hỏa","credit":"none"},{"text":"Thanh hóa đàm nhiệt","credit":"none"}],"phuong":[{"text":"Quy tỳ thang","credit":"full"},{"text":"Hoàng liên a giao thang","credit":"none"},{"text":"Long đởm tả can thang","credit":"none"},{"text":"Thiên vương bổ tâm đan","credit":"none"},{"text":"Ôn đởm thang","credit":"none"}],"huyet":[{"text":"Thần môn","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Tâm du","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Bách hội","credit":"full"},{"text":"Hợp cốc","credit":"none"},{"text":"Phong long","credit":"none"},{"text":"Thiên đột","credit":"none"}]},"action_options":[{"text":"Tư vấn vệ sinh giấc ngủ, giảm cà phê buổi chiều","time_minutes":3,"grade":"recommended","rationale":"Điều trị nền tảng"},{"text":"Kê Quy tỳ thang gia giảm","time_minutes":5,"grade":"recommended","rationale":"Phù hợp thể tâm tỳ lưỡng hư"},{"text":"Châm hoặc cứu Thần môn, Tam âm giao","time_minutes":15,"grade":"recommended","rationale":"Hỗ trợ an thần"},{"text":"Hẹn tái khám sau 2 tuần, đánh giá lại giấc ngủ","time_minutes":1,"grade":"recommended","rationale":"Theo dõi đáp ứng"},{"text":"Điều chỉnh chế độ ăn bổ huyết, điều trị thiếu máu nếu có","time_minutes":2,"grade":"recommended","rationale":"Theo kết quả xét nghiệm"},{"text":"Chỉ định chụp MRI sọ não","time_minutes":40,"grade":"waste","rationale":"Không có dấu hiệu thần kinh"},{"text":"Kê benzodiazepin dài ngày ngay lần khám đầu","time_minutes":2,"grade":"harmful","rationale":"Nguy cơ lệ thuộc, chưa tìm nguyên nhân"}],"teaching_explanation":"Mất ngủ mạn tính cần loại trừ nguyên nhân thực thể như cường giáp, thiếu máu, trầm cảm trước khi kết luận. Thể tâm tỳ lưỡng hư dùng Quy tỳ thang kèm châm cứu và tư vấn vệ sinh giấc ngủ. Thuốc an thần mạnh không phải lựa chọn đầu tiên."}'::jsonb,
  '273ac43a566160312b4ac69226ff07429d7c26c45639d4fb0b25915dbb04a96e'
)
