insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'liet-day-vii-ngoai-bien',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"liet-day-vii-ngoai-bien","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Méo miệng sau khi ngủ máy lạnh","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":34,"sex":"nam","patient_label":"Anh Vũ Minh Quân"},"presentation":{"intro":"Sáng nay anh thức dậy thấy miệng méo, mắt trái nhắm không kín, nước chảy khóe miệng. Tối qua ngủ máy lạnh thổi thẳng vào mặt.","place":"Phòng châm cứu","clock":"14:00","night":false},"vitals":{"hr":78,"sbp":125,"dbp":80,"rr":16,"temperature_c":36.8,"spo2":99},"history":[{"question":"Triệu chứng xuất hiện khi nào, đột ngột không?","response":"Sáng nay thức dậy mới thấy, không đau đầu."},{"question":"Có yếu tay chân, nói khó, tê nửa người không?","response":"Không, tay chân bình thường."},{"question":"Có đau sau tai, ù tai, nghe to bất thường không?","response":"Hơi đau sau tai bên trái, nghe hơi to."},{"question":"Có sốt, phát ban ở tai, tiền sử zona không?","response":"Không."},{"question":"Có chấn thương đầu mặt gần đây không?","response":"Không."},{"question":"Đái tháo đường, tăng huyết áp?","response":"Không biết, chưa khám."},{"question":"Ăn uống, vị giác?","response":"Ăn nhai nhớ, thấy mất vị giác một phần."},{"question":"Đã tự dùng thuốc gì?","response":"Uống thuốc giảm đau thông thường."}],"examination":[{"group":"V","item":"Quan sát nhăn trán, nhắm mắt","finding":"Trán bên trái không nhăn, mắt trái nhắm không kín, lộ củng mạc"},{"group":"V","item":"Quan sát nếp mũi má, miệng","finding":"Nếp mũi má mờ, miệng kéo sang bên phải"},{"group":"V","item":"Quan sát lưỡi","finding":"Lưỡi nhạt, rêu trắng mỏng"},{"group":"M","item":"Nói, thổi, huýt sáo","finding":"Nói hơi ngọng, không thổi được má trái"},{"group":"T","item":"Mạch","finding":"Phù, khẩn"},{"group":"K","item":"Khám thần kinh tay chân","finding":"Sức cơ 5 phần 5, không liệt chi"},{"group":"K","item":"Khám tai, ống tai ngoài","finding":"Không có mụn nước"},{"group":"K","item":"Đo huyết áp","finding":"125/80, bình thường"}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"5,2 mmol/L"},{"name":"Công thức máu","duration_minutes":20,"result":"Bình thường"},{"name":"Điện cơ thần kinh mặt","duration_minutes":40,"result":"Sẽ làm sau 1 đến 2 tuần nếu cần tiên lượng"},{"name":"Chụp CT sọ não","duration_minutes":30,"result":", không cần chụp"},{"name":"Chụp MRI cột sống cổ","duration_minutes":45,"result":"Không liên quan"}],"choices":{"diagnosis":{"ydx":["U góc cầu tiểu não","Liệt dây VII ngoại biên (liệt Bell)","Đột quỵ não","Zona tai (hội chứng Ramsay Hunt)","Viêm tai giữa biến chứng"],"bd":["Huyễn vựng","Khẩu nhãn oa tà","Đầu thống","Trúng phong tạng phủ","Trúng phong kinh lạc"],"bc":["Biểu thực nhiệt","Biểu thực hàn","Lý thực nhiệt","Biểu hư nhiệt","Lý hư hàn"],"the":["Can phong nội động","Phong hàn xâm nhập kinh lạc","Đàm ứ trở lạc","Khí huyết hư","Phong nhiệt xâm nhập kinh lạc"],"phap":["Khu phong tán hàn, thông kinh hoạt lạc","Thanh nhiệt giải độc","Bổ khí dưỡng huyết","Bình can tức phong","Hóa đàm khai khiếu"],"phuong":["Thiên ma câu đằng ẩm","Quy tỳ thang","Khiên chính tán gia giảm","Bổ dương hoàn ngũ thang","Ngân kiều tán"],"huyet":["Phong trì","Thiên đột","Giáp xa","Địa thương","Hợp cốc","Thái xung","Tam âm giao","Dương bạch"]},"actions":["Châm cứu nhẹ nhàng vùng mặt kết hợp xa gần","Điện châm cường độ mạnh vùng mặt ngay ngày đầu","Chụp CT sọ não thường quy","Chỉ định kháng sinh đường uống","Cho về không dặn chăm sóc mắt","Corticoid đường uống sớm trong 72 giờ đầu","Dặn tránh gió lạnh, tái khám sau 1 tuần","Chườm ấm nhẹ, xoa bóp nhẹ vùng mặt","Bảo vệ mắt: nhỏ nước mắt nhân tạo, che mắt khi ngủ"]}}'::jsonb,
  '2ba0c7d8a01b14d22a2465dff49ded80311eb40188483c3a00bbb03cc1f49ad2'
)
