insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'stemi-thanh-duoi',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"stemi-thanh-duoi","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau ngực cấp, nghi hội chứng vành cấp","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":61,"sex":"nam","patient_label":"Ông Lê Văn Hùng"},"presentation":{"intro":"Người bệnh được đưa đến khoa Cấp cứu vì đau ngực khi đang đi bộ nhanh. Đau sau xương ức kéo dài khoảng 40 phút, vã mồ hôi và buồn nôn. Có tiền sử hút thuốc; chưa ghi nhận dị ứng thuốc.","place":"Khoa Cấp cứu","clock":"08:20","night":false},"vitals":{"hr":104,"sbp":94,"dbp":62,"rr":24,"temperature_c":36.7,"spo2":93},"history":[{"question":"Đau bắt đầu khi nào và kéo dài bao lâu?","response":"Đau xuất hiện khoảng 40 phút trước, liên tục, chưa giảm."},{"question":"Đau ở đâu, có lan đi đâu không?","response":"Đau sau xương ức, lan lên hàm và mặt trong cánh tay trái."},{"question":"Đau có tính chất gì, mức độ ra sao?","response":"Cảm giác bóp nghẹt, nặng ngực, mức độ khoảng 8/10."},{"question":"Có khó thở, vã mồ hôi hoặc buồn nôn không?","response":"Khó thở nhẹ, vã mồ hôi lạnh và buồn nôn."},{"question":"Đã từng có cơn tương tự chưa?","response":"Vài tuần gần đây đôi lúc tức ngực khi gắng sức, tự hết sau nghỉ."},{"question":"Có bệnh nền hoặc yếu tố nguy cơ tim mạch nào?","response":"Hút thuốc nhiều năm; chưa được chẩn đoán bệnh mạch vành."},{"question":"Có dùng thuốc chống đông, thuốc tim mạch hoặc thuốc cường dương không?","response":"Không nhớ đã dùng thuốc tim mạch; không dùng thuốc cường dương gần đây."},{"question":"Có tiền sử dị ứng thuốc hoặc xuất huyết tiêu hóa không?","response":"Chưa biết dị ứng thuốc; chưa từng xuất huyết tiêu hóa."}],"examination":[{"group":"K","item":"Sắc mặt và mồ hôi","finding":"Sắc mặt tái, vã mồ hôi lạnh, vẻ lo lắng."},{"group":"K","item":"Tri giác","finding":"Tỉnh, trả lời được, có vẻ mệt."},{"group":"K","item":"Môi và đầu chi","finding":"Đầu chi hơi lạnh, không tím rõ."},{"group":"K","item":"Giọng nói và hơi thở","finding":"Nói được câu ngắn, hơi thở nhanh."},{"group":"K","item":"Tiếng thở","finding":"Không có tiếng rít; không ho khạc đàm."},{"group":"K","item":"Mạch","finding":"Mạch nhanh, hơi yếu, đều."},{"group":"K","item":"Tim phổi và tưới máu","finding":"Nhịp tim nhanh; phổi chưa nghe ran rõ; huyết áp thấp, đầu chi lạnh."}],"investigations":[{"name":"Điện tâm đồ 12 chuyển đạo","duration_minutes":5,"result":"ST chênh lên ở các chuyển đạo thành dưới; cần kích hoạt quy trình hội chẩn tái tưới máu."},{"name":"Troponin tim độ nhạy cao","duration_minutes":20,"result":"Tăng trên giới hạn tham chiếu; lấy mẫu nối tiếp theo quy trình cơ sở."},{"name":"Đường huyết mao mạch","duration_minutes":3,"result":"9,8 mmol/L."},{"name":"Công thức máu và sinh hóa cơ bản","duration_minutes":15,"result":"Chưa có kết quả bất thường cấp tính rõ; theo dõi chức năng thận và điện giải."},{"name":"CT sọ não không cản quang","duration_minutes":25,"result":"Không có chỉ định trong bệnh cảnh đau ngực này nếu không xuất hiện dấu thần kinh."}],"choices":{"diagnosis":{"ydx":["Thuyên tắc phổi nguy cơ thấp","Đau thắt ngực ổn định","Viêm màng ngoài tim cấp","Phình tách động mạch chủ","Hội chứng vành cấp có ST chênh lên, kèm giảm tưới máu"]},"actions":["Làm ECG 12 chuyển đạo ngay, lấy troponin và xét nghiệm cấp cứu","Đánh giá ABC, monitor ECG-SpO2-huyết áp và thiết lập đường truyền","Cho người bệnh đi bộ đến phòng chụp để hoàn tất thủ tục","Đánh giá chống chỉ định trước khi dùng thuốc kháng kết tập hoặc chống đông theo phác đồ","Đánh giá chỉ định oxy theo tình trạng thiếu oxy và quy trình cơ sở","Hội chẩn để tái tưới máu khẩn theo quy trình cơ sở","Kích hoạt báo động hội chứng vành cấp, gọi hỗ trợ tim mạch"]}}'::jsonb,
  'cdda4e205255f463f7a26bd9d56693d24f9be10a64293ee8604b11fd056e1166'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
