values (
  'stemi-thanh-duoi',
  '{"schema_version":"1.0.0","case_id":"stemi-thanh-duoi","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-acs-esc-2023-a84a21104b0c","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/37622654/","title":"ESC, Guidelines for the management of acute coronary syndromes, 2023.","organization":null,"year_version":null,"citation":"ESC, Guidelines for the management of acute coronary syndromes, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hội chứng vành cấp có ST chênh lên, kèm giảm tưới máu","credit":"full"},{"text":"Đau thắt ngực ổn định","credit":"none"},{"text":"Viêm màng ngoài tim cấp","credit":"none"},{"text":"Thuyên tắc phổi nguy cơ thấp","credit":"none"},{"text":"Phình tách động mạch chủ","credit":"none"}]},"action_options":[{"text":"Kích hoạt báo động hội chứng vành cấp, gọi hỗ trợ tim mạch","time_minutes":1,"grade":"critical","rationale":"Đau kéo dài, ECG gợi ý STEMI và huyết áp thấp."},{"text":"Đánh giá ABC, monitor ECG-SpO2-huyết áp và thiết lập đường truyền","time_minutes":2,"grade":"critical","rationale":"Theo dõi loạn nhịp và suy tuần hoàn."},{"text":"Làm ECG 12 chuyển đạo ngay, lấy troponin và xét nghiệm cấp cứu","time_minutes":5,"grade":"critical","rationale":"Xác định chẩn đoán và hướng xử trí."},{"text":"Hội chẩn để tái tưới máu khẩn theo quy trình cơ sở","time_minutes":5,"grade":"critical","rationale":"Nghi STEMI; không trì hoãn chuyển tuyến/can thiệp."},{"text":"Đánh giá chỉ định oxy theo tình trạng thiếu oxy và quy trình cơ sở","time_minutes":2,"grade":"recommended","rationale":"Không dùng oxy thường quy khi không có chỉ định."},{"text":"Đánh giá chống chỉ định trước khi dùng thuốc kháng kết tập hoặc chống đông theo phác đồ","time_minutes":3,"grade":"recommended","rationale":"Giảm nguy cơ huyết khối và tai biến chảy máu."},{"text":"Cho người bệnh đi bộ đến phòng chụp để hoàn tất thủ tục","time_minutes":2,"grade":"harmful","rationale":"Gắng sức và trì hoãn xử trí ở người bệnh nghi STEMI, tụt huyết áp."}],"teaching_explanation":"Đau ngực kéo dài, lan hàm/cánh tay, vã mồ hôi và ECG gợi ý STEMI cần kích hoạt xử trí khẩn. Đánh giá ABC, monitor, ECG và hội chẩn tái tưới máu là ưu tiên."}'::jsonb,
