insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'phan-ve-phu-thanh-quan',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"phan-ve-phu-thanh-quan","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Phản vệ sau dùng thuốc","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Chị Phạm Thị Ngọc"},"presentation":{"intro":"Khoảng 10 phút sau khi dùng một thuốc mới tại cơ sở y tế, người bệnh nổi ban ngứa toàn thân, khàn tiếng, khó thở và choáng. Tên thuốc đang được nhân viên kiểm tra trên hồ sơ.","place":"Khoa Cấp cứu","clock":"14:10","night":false},"vitals":{"hr":128,"sbp":76,"dbp":42,"rr":30,"temperature_c":36.5,"spo2":88},"history":[{"question":"Triệu chứng bắt đầu khi nào?","response":"Khoảng 10 phút sau khi dùng thuốc mới."},{"question":"Thuốc được dùng bằng đường nào và tên gì?","response":"Được tiêm tại cơ sở; người bệnh không nhớ tên thuốc, hồ sơ đang được kiểm tra."},{"question":"Có khó thở, khàn tiếng hoặc nghẹn họng không?","response":"Khó thở tăng nhanh, khàn tiếng và cảm giác nghẹn họng."},{"question":"Có ngứa, mày đay hoặc phù môi lưỡi không?","response":"Ngứa toàn thân, nổi mày đay, môi hơi sưng."},{"question":"Có đau bụng, nôn hoặc tiêu chảy không?","response":"Đau quặn bụng và buồn nôn."},{"question":"Đã từng phản ứng tương tự hoặc dị ứng thuốc chưa?","response":"Từng nổi mẩn sau một thuốc giảm đau nhưng không rõ tên."},{"question":"Có hen phế quản hoặc bệnh tim mạch không?","response":"Có hen nhẹ từ nhỏ, hiện không dùng thuốc thường xuyên."},{"question":"Có chóng mặt, ngất hoặc cảm giác sắp ngất không?","response":"Choáng váng, mắt tối sầm khi ngồi dậy."}],"examination":[{"group":"K","item":"Da và niêm mạc","finding":"Mày đay lan rộng, đỏ da; môi phù nhẹ."},{"group":"K","item":"Tri giác","finding":"Bứt rứt, còn đáp ứng nhưng yếu."},{"group":"K","item":"Đường thở trên","finding":"Khàn tiếng, phù môi; cần đánh giá nguy cơ phù thanh quản."},{"group":"K","item":"Giọng nói","finding":"Khàn tiếng mới xuất hiện."},{"group":"K","item":"Âm thở","finding":"Thở rít nhẹ khi hít vào, có khò khè."},{"group":"K","item":"Mạch","finding":"Mạch nhanh nhỏ, đầu chi lạnh."},{"group":"K","item":"Tuần hoàn và hô hấp","finding":"Hạ huyết áp, giảm SpO2, ran rít hai phế trường."}],"investigations":[{"name":"Đánh giá ABC, huyết áp và SpO2 liên tục","duration_minutes":1,"result":"Đường thở có dấu hiệu bị ảnh hưởng, SpO2 thấp, tụt huyết áp."},{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"6,1 mmol/L."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp nhanh xoang."},{"name":"Tryptase huyết thanh theo thời điểm và khả năng cơ sở","duration_minutes":30,"result":"Chưa có kết quả; không chờ xét nghiệm mới bắt đầu xử trí."},{"name":"CT ngực có cản quang","duration_minutes":30,"result":"Không phải xét nghiệm ưu tiên trong phản vệ điển hình đang diễn tiến."}],"choices":{"diagnosis":{"ydx":["Phản vệ nặng sau dùng thuốc, suy hô hấp và tụt huyết áp","Ngộ độc thức ăn","Cơn hen phế quản đơn thuần","Mày đay cấp không biến chứng","Cơn hoảng loạn"]},"actions":["Dùng adrenalin đường tiêm bắp theo hướng dẫn phản vệ hiện hành và quy trình cơ sở","Ngừng ngay thuốc nghi gây phản vệ, gọi hỗ trợ và báo động cấp cứu","Theo dõi liên tục và ghi nhận diễn biến, thời điểm dùng thuốc","Cho uống thuốc kháng histamin thay cho adrenalin","Chờ kết quả tryptase mới điều trị","Hỗ trợ oxy, thiết lập đường truyền và hồi sức dịch theo quy trình","Đặt người bệnh nằm phù hợp tình trạng tuần hoàn, đánh giá ABC liên tục","Chuẩn bị kiểm soát đường thở nâng cao nếu phù thanh quản tiến triển"]}}'::jsonb,
  '5315015920fdb95e160707acf3c4a33a2a637816750fb7594a3cd16a826b2063'
)
on conflict (case_id) do update set
