values (
  'phan-ve-phu-thanh-quan',
  '{"schema_version":"1.0.0","case_id":"phan-ve-phu-thanh-quan","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-byt-tt51-2017","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/thong-tu-51-2017-tt-byt-bo-y-te-158294-d1.html","title":"Bộ Y tế, Thông tư 51/2017/TT-BYT hướng dẫn phòng, chẩn đoán và xử trí phản vệ, 2017.","organization":null,"year_version":null,"citation":"Bộ Y tế, Thông tư 51/2017/TT-BYT hướng dẫn phòng, chẩn đoán và xử trí phản vệ, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-anaphylaxis-wao-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/33204386/","title":"World Allergy Organization, Anaphylaxis Guidance, 2020.","organization":null,"year_version":null,"citation":"World Allergy Organization, Anaphylaxis Guidance, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5,7],"examination_essential_indices":[0,1,2,3,4,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Phản vệ nặng sau dùng thuốc, suy hô hấp và tụt huyết áp","credit":"full"},{"text":"Cơn hen phế quản đơn thuần","credit":"none"},{"text":"Mày đay cấp không biến chứng","credit":"none"},{"text":"Ngộ độc thức ăn","credit":"none"},{"text":"Cơn hoảng loạn","credit":"none"}]},"action_options":[{"text":"Ngừng ngay thuốc nghi gây phản vệ, gọi hỗ trợ và báo động cấp cứu","time_minutes":1,"grade":"critical","rationale":"Loại bỏ tiếp xúc tiếp diễn và huy động nhân lực."},{"text":"Đặt người bệnh nằm phù hợp tình trạng tuần hoàn, đánh giá ABC liên tục","time_minutes":1,"grade":"critical","rationale":"Tụt huyết áp và nguy cơ suy hô hấp."},{"text":"Dùng adrenalin đường tiêm bắp theo hướng dẫn phản vệ hiện hành và quy trình cơ sở","time_minutes":1,"grade":"critical","rationale":"Điều trị hàng đầu; không chờ xét nghiệm."},{"text":"Hỗ trợ oxy, thiết lập đường truyền và hồi sức dịch theo quy trình","time_minutes":3,"grade":"critical","rationale":"Giảm oxy máu và sốc."},{"text":"Chuẩn bị kiểm soát đường thở nâng cao nếu phù thanh quản tiến triển","time_minutes":2,"grade":"recommended","rationale":"Khàn tiếng, nghẹn họng và thở rít."},{"text":"Theo dõi liên tục và ghi nhận diễn biến, thời điểm dùng thuốc","time_minutes":1,"grade":"recommended","rationale":"Phản vệ có thể tái diễn hoặc tiến triển."},{"text":"Chờ kết quả tryptase mới điều trị","time_minutes":30,"grade":"harmful","rationale":"Xét nghiệm không được làm trì hoãn xử trí phản vệ."},{"text":"Cho uống thuốc kháng histamin thay cho adrenalin","time_minutes":2,"grade":"harmful","rationale":"Không xử trí được sốc hoặc tắc nghẽn đường thở."}],"teaching_explanation":"Khởi phát nhanh sau dùng thuốc, tổn thương da-niêm mạc kèm khó thở và tụt huyết áp gợi ý phản vệ nặng. Ngừng tác nhân, kích hoạt cấp cứu và dùng adrenalin theo hướng dẫn hiện hành là ưu tiên; không chờ xét nghiệm. Kháng histamin không thay thế điều trị đầu tay."}'::jsonb,
  '958c4f7fb34638e0498ad5d0e3eb3d1781970b0a438bd3d0321a919a13b67338'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

