values (
  'dot-quy-thieu-mau-cap',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"dot-quy-thieu-mau-cap","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Yếu liệt nửa người khởi phát đột ngột","setting":"capcuu","level":"Khó","track":"noi","mode":"tay","specialty":null,"demographics":{"age":70,"sex":"nữ","patient_label":"Bà Nguyễn Thị Sen"},"presentation":{"intro":"Người nhà đưa đến vì đột ngột méo miệng, nói khó và yếu tay chân phải. Lần cuối còn bình thường được ghi nhận lúc 16:00. Có tiền sử tăng huyết áp và rung nhĩ.","place":"Khoa Cấp cứu","clock":"16:40","night":false},"vitals":{"hr":112,"sbp":184,"dbp":102,"rr":20,"temperature_c":36.8,"spo2":96},"history":[{"question":"Thời điểm cuối cùng người bệnh còn bình thường là khi nào?","response":"Người nhà xác nhận lúc 16:00 người bệnh vẫn nói và đi lại bình thường."},{"question":"Triệu chứng khởi phát đột ngột hay tăng dần?","response":"Khởi phát đột ngột khi đang ngồi xem tivi."},{"question":"Có yếu hoặc tê một bên người không?","response":"Yếu tay chân phải, cầm rơi đồ vật."},{"question":"Có méo miệng, nói khó hoặc không hiểu lời nói không?","response":"Méo miệng và nói khó; vẫn hiểu câu hỏi."},{"question":"Có đau đầu dữ dội, co giật hoặc mất ý thức không?","response":"Không đau đầu dữ dội, không co giật, không mất ý thức."},{"question":"Có tiền sử rung nhĩ hoặc dùng thuốc chống đông không?","response":"Có rung nhĩ; gia đình chưa rõ tên thuốc đang dùng."},{"question":"Có đái tháo đường hoặc từng hạ đường huyết không?","response":"Chưa được chẩn đoán đái tháo đường."},{"question":"Người bệnh có nuốt được nước an toàn không?","response":"Chưa thử cho uống; người bệnh nói khó và chảy dãi nhẹ."}],"examination":[{"group":"K","item":"Mặt","finding":"Lệch nhân trung, méo miệng khi cười."},{"group":"K","item":"Tri giác","finding":"Tỉnh, tiếp xúc được, làm theo một số yêu cầu."},{"group":"K","item":"Vận động","finding":"Tay phải rơi khi giơ lên; chân phải yếu."},{"group":"K","item":"Ngôn ngữ","finding":"Nói khó, phát âm không rõ; hiểu lời đơn giản."},{"group":"K","item":"Đường thở","finding":"Tự thở, có ít nước bọt đọng; cần lưu ý nguy cơ sặc."},{"group":"K","item":"Mạch","finding":"Không đều, nhanh."},{"group":"K","item":"Khám thần kinh khu trú","finding":"Yếu nửa người phải, không cứng gáy; cần lượng giá mức độ thiếu hụt theo quy trình."}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"7,2 mmol/L; không giải thích được thiếu hụt thần kinh."},{"name":"CT sọ não không cản quang khẩn","duration_minutes":15,"result":"Chưa thấy xuất huyết nội sọ; tiếp tục đánh giá theo quy trình đột quỵ."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Rung nhĩ với đáp ứng thất nhanh."},{"name":"Công thức máu, đông máu, điện giải và chức năng thận","duration_minutes":15,"result":"Đang xử lý khẩn; cần kết quả theo quy trình trước quyết định điều trị."},{"name":"CT bụng có cản quang","duration_minutes":30,"result":"Không có chỉ định trong đánh giá ban đầu đột quỵ cấp."}],"choices":{"diagnosis":{"ydx":["Hạ đường huyết có triệu chứng","Xuất huyết não đã chắc chắn","Đột quỵ não cấp, nghi thiếu máu não do rung nhĩ","Cơn migraine có triệu chứng thần kinh","Liệt dây VII ngoại biên đơn thuần"]},"actions":["Cho uống nước hoặc thuốc khi chưa đánh giá nuốt","Chụp CT sọ não khẩn và hội chẩn nhóm đột quỵ","Giữ nhịn ăn uống đến khi sàng lọc nuốt an toàn","Thu thập danh sách thuốc chống đông và bệnh sử rung nhĩ","Đo đường huyết mao mạch ngay","Đánh giá ABC, monitor, thiết lập đường truyền và lượng giá thần kinh","Kích hoạt quy trình đột quỵ và ghi nhận chính xác thời điểm cuối bình thường"]}}'::jsonb,
  '35dc902f1e96bd4f7a1f0cbf06599021372c2c838da11699b80c9a53ff70b5bd'
)
on conflict (case_id) do update set
