insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'dot-quy-thieu-mau-cap',
  '{"schema_version":"1.0.0","case_id":"dot-quy-thieu-mau-cap","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ais-aha-2026","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/41582814/","title":"AHA/ASA, Guideline for the Early Management of Patients With Acute Ischemic Stroke, 2026.","organization":null,"year_version":null,"citation":"AHA/ASA, Guideline for the Early Management of Patients With Acute Ischemic Stroke, 2026.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,2,3,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đột quỵ não cấp, nghi thiếu máu não do rung nhĩ","credit":"full"},{"text":"Xuất huyết não đã chắc chắn","credit":"none"},{"text":"Liệt dây VII ngoại biên đơn thuần","credit":"none"},{"text":"Hạ đường huyết có triệu chứng","credit":"none"},{"text":"Cơn migraine có triệu chứng thần kinh","credit":"none"}]},"action_options":[{"text":"Kích hoạt quy trình đột quỵ và ghi nhận chính xác thời điểm cuối bình thường","time_minutes":1,"grade":"critical","rationale":"Thời gian quyết định khả năng điều trị tái tưới máu."},{"text":"Đánh giá ABC, monitor, thiết lập đường truyền và lượng giá thần kinh","time_minutes":3,"grade":"critical","rationale":"Theo dõi diễn tiến và bảo đảm an toàn ban đầu."},{"text":"Đo đường huyết mao mạch ngay","time_minutes":2,"grade":"critical","rationale":"Loại trừ hạ đường huyết giả đột quỵ."},{"text":"Chụp CT sọ não khẩn và hội chẩn nhóm đột quỵ","time_minutes":15,"grade":"critical","rationale":"Phân biệt xuất huyết và thiếu máu, đánh giá điều trị phù hợp."},{"text":"Giữ nhịn ăn uống đến khi sàng lọc nuốt an toàn","time_minutes":1,"grade":"recommended","rationale":"Giảm nguy cơ sặc."},{"text":"Thu thập danh sách thuốc chống đông và bệnh sử rung nhĩ","time_minutes":3,"grade":"recommended","rationale":"Ảnh hưởng quyết định điều trị cấp."},{"text":"Cho uống nước hoặc thuốc khi chưa đánh giá nuốt","time_minutes":1,"grade":"harmful","rationale":"Nguy cơ sặc do rối loạn nuốt."}],"teaching_explanation":"Ghi chính xác lần cuối còn bình thường, kích hoạt quy trình đột quỵ, kiểm tra đường huyết và chụp sọ não khẩn. Chưa cho ăn uống khi chưa sàng lọc nuốt."}'::jsonb,
  '884d3611020bc2f089fb4c590378f4b72637a7e5b4c6499594ae04ae182a3c21'
)
