insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ha-duong-huyet-nang',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ha-duong-huyet-nang","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Rối loạn tri giác do hạ đường huyết nặng","setting":"capcuu","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông Trần Văn Bảy"},"presentation":{"intro":"Người nhà phát hiện người bệnh vã mồ hôi, run, lơ mơ lúc gần sáng. Người bệnh mắc đái tháo đường type 2, đang dùng thuốc hạ đường huyết; tối qua ăn ít nhưng vẫn dùng thuốc như thường lệ.","place":"Khoa Cấp cứu","clock":"05:50","night":true},"vitals":{"hr":116,"sbp":102,"dbp":66,"rr":18,"temperature_c":36.4,"spo2":97},"history":[{"question":"Triệu chứng được phát hiện lúc nào?","response":"Người nhà phát hiện khoảng 20 phút trước khi đến viện."},{"question":"Người bệnh đã ăn uống thế nào tối qua?","response":"Ăn rất ít vì buồn nôn."},{"question":"Có dùng thuốc điều trị đái tháo đường không?","response":"Có uống thuốc như thường lệ nhưng gia đình chưa nhớ tên."},{"question":"Có run, vã mồ hôi, đói cồn cào hoặc hồi hộp không?","response":"Run tay, vã mồ hôi và tim đập nhanh."},{"question":"Có co giật, ngất hoặc lú lẫn không?","response":"Lơ mơ, trả lời chậm; không ghi nhận co giật."},{"question":"Đã từng có cơn hạ đường huyết chưa?","response":"Từng run vã mồ hôi khi bỏ bữa, chưa phải nhập viện."},{"question":"Có sốt, ho hoặc đau ngực không?","response":"Không sốt, không ho, không đau ngực."},{"question":"Có thể tự nuốt an toàn lúc này không?","response":"Không trả lời mạch lạc, không làm theo yêu cầu nuốt."}],"examination":[{"group":"K","item":"Da","finding":"Da ẩm, vã mồ hôi."},{"group":"K","item":"Tri giác","finding":"Lơ mơ, gọi mở mắt, định hướng kém."},{"group":"K","item":"Run","finding":"Run đầu chi."},{"group":"K","item":"Lời nói","finding":"Nói chậm, câu trả lời không phù hợp."},{"group":"K","item":"Hơi thở","finding":"Không có mùi ceton rõ; thở đều."},{"group":"K","item":"Mạch","finding":"Nhanh, đều."},{"group":"K","item":"Thần kinh và nuốt","finding":"Không thấy yếu liệt khu trú rõ; phản xạ bảo vệ đường thở giảm do lơ mơ."}],"investigations":[{"name":"Đường huyết mao mạch tại giường","duration_minutes":1,"result":"2,1 mmol/L."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp nhanh xoang."},{"name":"Điện giải, ure và creatinin","duration_minutes":20,"result":"Đang chờ; đánh giá yếu tố nguy cơ tái hạ đường huyết và bệnh kèm."},{"name":"HbA1c","duration_minutes":30,"result":"Chưa có kết quả; không cần chờ để xử trí cơn cấp."},{"name":"CT sọ não","duration_minutes":25,"result":"Không phải bước đầu nếu tri giác cải thiện sau xử trí hạ đường huyết và không có dấu khu trú/chấn thương."}],"choices":{"diagnosis":{"ydx":["Đột quỵ não chắc chắn","Ngộ độc opioid","Nhiễm toan ceton do đái tháo đường","Hạ đường huyết nặng có rối loạn tri giác","Tăng áp lực nội sọ"]},"actions":["Cho tiêm thêm thuốc hạ đường huyết vì đường huyết dao động","Đánh giá lại tri giác và glucose sau xử trí, theo dõi tái hạ đường huyết","Bù glucose bằng đường phù hợp khi người bệnh không nuốt an toàn, theo quy trình cơ sở","Đánh giá ABC, bảo vệ đường thở và đo glucose mao mạch ngay","Theo dõi và lập kế hoạch ăn uống/điều chỉnh thuốc sau khi tỉnh, có người phụ trách chuyên môn","Cho uống nước đường khi người bệnh lơ mơ và nuốt không an toàn","Rà soát thuốc, bữa ăn, chức năng thận và nguyên nhân bỏ bữa"]}}'::jsonb,
  '7971517541733a571a969f50b058a426b4a4179de4fb54a2fefb2116a8c556b9'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'ha-duong-huyet-nang',
  '{"schema_version":"1.0.0","case_id":"ha-duong-huyet-nang","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ha-duong-huyet-nang-1","resource_type":"other","source":"American Diabetes Association, Glycemic Goals, Hypoglycemia, and Hyperglycemic Crises: Standards of Care in Diabetes, 2026.","title":"American Diabetes Association, Glycemic Goals, Hypoglycemia, and Hyperglycemic Crises: Standards of Care in Diabetes, 2026.","organization":null,"year_version":null,"citation":"American Diabetes Association, Glycemic Goals, Hypoglycemia, and Hyperglycemic Crises: Standards of Care in Diabetes, 2026.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,7],"examination_essential_indices":[0,1,2,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hạ đường huyết nặng có rối loạn tri giác","credit":"full"},{"text":"Nhiễm toan ceton do đái tháo đường","credit":"none"},{"text":"Đột quỵ não chắc chắn","credit":"none"},{"text":"Ngộ độc opioid","credit":"none"},{"text":"Tăng áp lực nội sọ","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, bảo vệ đường thở và đo glucose mao mạch ngay","time_minutes":1,"grade":"critical","rationale":"Tri giác giảm và có biểu hiện giao cảm."},{"text":"Bù glucose bằng đường phù hợp khi người bệnh không nuốt an toàn, theo quy trình cơ sở","time_minutes":2,"grade":"critical","rationale":"Hạ đường huyết nặng; tránh cho uống gây sặc."},{"text":"Đánh giá lại tri giác và glucose sau xử trí, theo dõi tái hạ đường huyết","time_minutes":5,"grade":"critical","rationale":"Nguy cơ tái diễn, nhất là khi thuốc còn tác dụng."},{"text":"Rà soát thuốc, bữa ăn, chức năng thận và nguyên nhân bỏ bữa","time_minutes":5,"grade":"recommended","rationale":"Tìm nguyên nhân để phòng tái phát."},{"text":"Theo dõi và lập kế hoạch ăn uống/điều chỉnh thuốc sau khi tỉnh, có người phụ trách chuyên môn","time_minutes":10,"grade":"recommended","rationale":"Ngăn tái hạ đường huyết."},{"text":"Cho uống nước đường khi người bệnh lơ mơ và nuốt không an toàn","time_minutes":1,"grade":"harmful","rationale":"Nguy cơ sặc và tắc đường thở."},{"text":"Cho tiêm thêm thuốc hạ đường huyết vì đường huyết dao động","time_minutes":1,"grade":"harmful","rationale":"Làm nặng thêm hạ đường huyết."}],"teaching_explanation":"Lơ mơ, run và vã mồ hôi ở người dùng thuốc hạ đường huyết cần đo glucose ngay. Với rối loạn tri giác, không cho ăn hoặc uống; chọn đường bù glucose phù hợp và theo dõi đáp ứng cũng như tái hạ đường huyết. Sau ổn định cần rà lại thuốc, bữa ăn và yếu tố nguy cơ."}'::jsonb,
  '89c6b9413017976dc6fda991ca104c7b9b76e36db3c1b83c156e1f394c9dce5c'
)
