  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'xhth-tren-xo-gan',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"xhth-tren-xo-gan","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn máu và đi ngoài phân đen","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":67,"sex":"nam","patient_label":"Ông Đặng Văn Tám"},"presentation":{"intro":"Người bệnh nôn ra máu đỏ sẫm hai lần và đi ngoài phân đen trong ngày. Có tiền sử xơ gan do rượu; gần đây mệt tăng. Gia đình không rõ người bệnh có đang dùng thuốc chống đông hay không.","place":"Khoa Cấp cứu","clock":"23:15","night":true},"vitals":{"hr":122,"sbp":88,"dbp":54,"rr":24,"temperature_c":36.6,"spo2":95},"history":[{"question":"Nôn máu bắt đầu khi nào và số lần?","response":"Nôn máu đỏ sẫm hai lần trong vài giờ gần đây."},{"question":"Lượng máu ước tính và có cục máu không?","response":"Gia đình thấy một lượng đáng kể, có lẫn cục máu; không cân đo được."},{"question":"Phân có màu đen, dính và mùi khẳm không?","response":"Đi ngoài phân đen, dính, mùi khẳm từ sáng."},{"question":"Có chóng mặt, ngất hoặc yếu lả không?","response":"Choáng khi đứng, mệt lả."},{"question":"Có tiền sử bệnh gan, loét dạ dày hoặc xuất huyết tiêu hóa không?","response":"Được chẩn đoán xơ gan; từng đau thượng vị nhưng chưa nội soi gần đây."},{"question":"Có dùng thuốc chống đông, aspirin hoặc thuốc giảm đau kháng viêm không?","response":"Gia đình không rõ; cần kiểm tra toa thuốc."},{"question":"Có uống rượu gần đây không?","response":"Có uống rượu nhiều năm, gần đây vẫn uống."},{"question":"Có đau bụng dữ dội hoặc sốt không?","response":"Không đau bụng dữ dội, không sốt."}],"examination":[{"group":"K","item":"Da và niêm mạc","finding":"Da nhợt, niêm mạc nhạt."},{"group":"K","item":"Tri giác","finding":"Tỉnh nhưng mệt, trả lời chậm."},{"group":"K","item":"Bụng","finding":"Bụng hơi chướng, có tuần hoàn bàng hệ nhẹ."},{"group":"K","item":"Chất nôn","finding":"Có dịch nôn màu đỏ sẫm lẫn cục máu theo ghi nhận của gia đình."},{"group":"K","item":"Hơi thở","finding":"Không khó thở rõ; có mùi rượu nhẹ."},{"group":"K","item":"Mạch","finding":"Nhanh nhỏ, đầu chi lạnh."},{"group":"K","item":"Tuần hoàn và bụng","finding":"Hạ huyết áp tư thế/choáng, bụng mềm, không phản ứng thành bụng."}],"investigations":[{"name":"Công thức máu","duration_minutes":15,"result":"Hb 7,8 g/dL; cần diễn giải cùng tình trạng huyết động và diễn tiến chảy máu."},{"name":"Nhóm máu, sàng lọc kháng thể và phản ứng chéo","duration_minutes":20,"result":"Đang tiến hành chuẩn bị chế phẩm máu nếu có chỉ định."},{"name":"Ure, creatinin, điện giải và chức năng gan","duration_minutes":20,"result":"Ure tăng; cần đánh giá bệnh gan và rối loạn chuyển hóa."},{"name":"Đông máu","duration_minutes":15,"result":"INR tăng nhẹ; cần tìm thuốc chống đông và bệnh gan liên quan."},{"name":"CT sọ não","duration_minutes":30,"result":"Không có chỉ định ban đầu khi không có triệu chứng thần kinh hoặc chấn thương."}],"choices":{"diagnosis":{"ydx":["Viêm dạ dày không biến chứng","Hội chứng Mallory Weiss đơn thuần","Tắc ruột","Xuất huyết tiêu hóa dưới","Xuất huyết tiêu hóa trên có sốc giảm thể tích, nghi tăng áp cửa"]},"actions":["Hồi sức tuần hoàn, đánh giá đáp ứng và chỉ định truyền máu theo hướng dẫn hiện hành","Cho người bệnh về nhà vì nôn máu đã tạm ngừng","Hội chẩn tiêu hóa/nội soi và đánh giá nguyên nhân tăng áp cửa hoặc loét","Gọi hỗ trợ cấp cứu, đánh giá ABC và theo dõi huyết động liên tục","Thiết lập đường truyền ngoại vi phù hợp, lấy xét nghiệm và chuẩn bị chế phẩm máu theo quy trình","Giữ nhịn ăn uống, chuẩn bị đường thở nếu nôn máu nhiều hoặc tri giác giảm","Rà soát thuốc chống đông, kháng kết tập và NSAID; đánh giá chức năng gan/đông máu"]}}'::jsonb,
  '5b8528a1261a791e512c1978b19a656165cb928e57e1f6f23484fe66a3518513'
)
