insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'xhth-tren-xo-gan',
  '{"schema_version":"1.0.0","case_id":"xhth-tren-xo-gan","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-baveno-vii","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/35120736/","title":"Baveno VII, Renewing Consensus in Portal Hypertension, 2022.","organization":null,"year_version":null,"citation":"Baveno VII, Renewing Consensus in Portal Hypertension, 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-ptu-wses-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31921329/","title":"World Society of Emergency Surgery, Perforated and Bleeding Peptic Ulcer: WSES Guidelines, 2020.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery, Perforated and Bleeding Peptic Ulcer: WSES Guidelines, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,3,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"essential"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Xuất huyết tiêu hóa trên có sốc giảm thể tích, nghi tăng áp cửa","credit":"full"},{"text":"Xuất huyết tiêu hóa dưới","credit":"none"},{"text":"Viêm dạ dày không biến chứng","credit":"none"},{"text":"Tắc ruột","credit":"none"},{"text":"Hội chứng Mallory Weiss đơn thuần","credit":"none"}]},"action_options":[{"text":"Gọi hỗ trợ cấp cứu, đánh giá ABC và theo dõi huyết động liên tục","time_minutes":1,"grade":"critical","rationale":"Nôn máu kèm tụt huyết áp, mạch nhanh."},{"text":"Thiết lập đường truyền ngoại vi phù hợp, lấy xét nghiệm và chuẩn bị chế phẩm máu theo quy trình","time_minutes":5,"grade":"critical","rationale":"Có dấu hiệu sốc và thiếu máu."},{"text":"Hồi sức tuần hoàn, đánh giá đáp ứng và chỉ định truyền máu theo hướng dẫn hiện hành","time_minutes":5,"grade":"critical","rationale":"Không trì hoãn hồi sức khi huyết động không ổn định."},{"text":"Hội chẩn tiêu hóa/nội soi và đánh giá nguyên nhân tăng áp cửa hoặc loét","time_minutes":5,"grade":"critical","rationale":"Cần kiểm soát nguồn chảy máu."},{"text":"Rà soát thuốc chống đông, kháng kết tập và NSAID; đánh giá chức năng gan/đông máu","time_minutes":5,"grade":"recommended","rationale":"Các yếu tố này ảnh hưởng chảy máu và kế hoạch điều trị."},{"text":"Giữ nhịn ăn uống, chuẩn bị đường thở nếu nôn máu nhiều hoặc tri giác giảm","time_minutes":2,"grade":"recommended","rationale":"Giảm nguy cơ sặc."},{"text":"Cho người bệnh về nhà vì nôn máu đã tạm ngừng","time_minutes":1,"grade":"harmful","rationale":"Có thể tiếp tục xuất huyết và sốc."}],"teaching_explanation":"Nôn máu, phân đen, mạch nhanh và huyết áp thấp gợi ý xuất huyết tiêu hóa trên có giảm thể tích tuần hoàn. Ưu tiên ABC, theo dõi, đường truyền, xét nghiệm/chuẩn bị máu và phối hợp kiểm soát nguồn chảy máu. Cần rà soát thuốc chống đông, thuốc kháng kết tập, NSAID và bệnh gan."}'::jsonb,
  '56d7265c5c4e3ea5e1eda12f37c998fb8d7aef23eda22242ebefc48614f41f64'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'co-giat-do-sot-cao-tre-em',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"co-giat-do-sot-cao-tre-em","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Trẻ 2 tuổi sốt cao, đang co giật","setting":"capcuu","level":"Dễ","track":"noi","mode":"tay","specialty":null,"demographics":{"age":2,"sex":"nam","patient_label":"Bé Đặng Gia Bảo"},"presentation":{"intro":"Mẹ bế bé vào khoa Cấp cứu lúc nửa đêm vì bé lên cơn co giật toàn thân khoảng 5 phút trước, đến giờ vẫn chưa dừng hẳn. Bé sốt từ chiều, ho và sổ mũi hai ngày nay.","place":"Khoa Cấp cứu Nhi","clock":"02:40","night":true},"vitals":{"hr":168,"sbp":96,"dbp":58,"rr":38,"temperature_c":39.8,"spo2":90},"history":[{"question":"Cơn co giật bắt đầu khi nào, đã kéo dài bao lâu?","response":"Khoảng 5 phút trước, bé co cứng rồi giật cả hai tay chân, mắt trợn ngược, đến giờ vẫn chưa dừng hẳn."},{"question":"Cơn giật là cả người hay một bên? Môi bé có tím không?","response":"Giật cả hai bên người, môi hơi tím."},{"question":"Bé sốt từ khi nào, cao nhất bao nhiêu? Đã cho uống thuốc hạ sốt chưa?","response":"Sốt từ chiều nay, ở nhà đo được 39,5 độ, chưa kịp cho uống thuốc hạ sốt."},{"question":"Có ho, sổ mũi, đau họng, nôn ói hoặc tiêu chảy kèm theo không?","response":"Ho, sổ mũi hai ngày nay. Không nôn, không tiêu chảy."},{"question":"Trước cơn bé có quấy khóc dữ dội, nôn vọt, nổi ban hoặc li bì không?","response":"Không nôn vọt, không nổi ban. Trước cơn bé vẫn chơi và bú được."},{"question":"Bé đã từng co giật lần nào chưa? Gia đình có ai bị sốt co giật hoặc động kinh không?","response":"Đây là lần đầu. Anh ruột lúc nhỏ có bị sốt co giật."},{"question":"Bé có ngã đập đầu hoặc uống nhầm thuốc, hóa chất không?","response":"Không ngã, không uống nhầm thuốc."},{"question":"Tiền sử sinh nở, phát triển và tiêm chủng của bé?","response":"Sinh đủ tháng, phát triển bình thường, tiêm chủng đủ theo lịch."},{"question":"Mấy ngày nay bé ăn bú thế nào?","response":"Vẫn bú được, hơi kém hơn ngày thường."}],"examination":[{"group":"K","item":"Quan sát cơn co giật","finding":"Co giật toàn thể kiểu cứng rồi giật, mắt trợn ngược, thở nông, chưa dừng sau khoảng 5 phút."},{"group":"K","item":"Da và môi","finding":"Da đỏ, nóng, vã mồ hôi; môi tím nhẹ."},{"group":"K","item":"Da, thóp, phù","finding":"Không có ban xuất huyết, không phù."},{"group":"K","item":"Tiếng thở","finding":"Thở nhanh, có tiếng khò khè đờm dãi ở họng, không rít thanh quản."},{"group":"K","item":"Mùi hơi thở và chất nôn","finding":"Không có mùi hóa chất lạ."},{"group":"K","item":"Mạch và da","finding":"Mạch quay nhanh, nảy, đều; da nóng ẩm."},{"group":"K","item":"Khám họng, tai","finding":"Họng đỏ, amidan sung huyết, không có mủ; màng nhĩ bình thường."},{"group":"K","item":"Dấu hiệu màng não và thần kinh","finding":"Khi cơn giật tạm ngưng: cổ mềm, Brudzinski âm tính, không có dấu thần kinh khu trú."},{"group":"K","item":"Khám phổi và tim","finding":"Phổi thô, ít ran ngáy; tim nhanh đều, không có âm thổi."}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"4,8 mmol/L, loại trừ hạ đường huyết."},{"name":"Công thức máu và CRP","duration_minutes":15,"result":"Bạch cầu 12 G/L, CRP không cao, gợi ý nhiễm virus."},{"name":"Điện giải đồ và canxi máu","duration_minutes":15,"result":"Natri, canxi trong giới hạn bình thường."},{"name":"Test nhanh cúm A và B","duration_minutes":15,"result":"Âm tính."},{"name":"Chọc dò dịch não tủy","duration_minutes":30,"result":"Chỉ làm khi có dấu màng não hoặc nghi ngờ viêm màng não; ở ca này không có chỉ định thường quy."},{"name":"CT sọ não không cản quang","duration_minutes":30,"result":"Không có chỉ định: không chấn thương, không dấu thần kinh khu trú, bé hồi phục tri giác."},{"name":"Điện não đồ","duration_minutes":30,"result":"Không có chỉ định thường quy sau một cơn sốt co giật đơn thuần."}],"choices":{"diagnosis":{"ydx":["Ngộ độc thuốc hoặc hóa chất gây co giật","Động kinh toàn thể khởi phát sớm","Viêm màng não mủ","Co giật do hạ canxi máu","Co giật do sốt đơn thuần, cơn kéo dài cần cắt cơn","Hạ đường huyết gây co giật"]},"actions":["Thở oxy qua mặt nạ, theo dõi SpO2 và nhịp thở liên tục","Dùng kháng sinh phổ rộng tĩnh mạch thường quy","Lau người bằng cồn hoặc chườm nước đá","Nhét vật cứng hoặc muỗng vào miệng bé để chống cắn lưỡi","Theo dõi tại khoa cấp cứu vài giờ sau cơn, đánh giá lại tri giác và dấu màng não","Thiết lập đường truyền tĩnh mạch ngoại vi","Cắt cơn bằng thuốc nhóm benzodiazepin theo phác đồ nhi khoa, theo dõi nhịp thở sau dùng","Đặt bé nằm nghiêng an toàn, nới quần áo, hút đờm dãi, giữ thông thoáng đường thở","Cho phenobarbital dự phòng kéo dài","Cho bé uống thuốc hạ sốt và nước trong khi đang co giật","Giải thích cho cha mẹ cách xử trí khi bé giật lại, không nhét vật vào miệng","Hạ sốt bằng paracetamol sau khi hết giật, kết hợp lau ấm"]}}'::jsonb,
  '9e4ee9ad3258d170fa5c425211cda0190a75edf788689768bf1a6e9b532217c1'
)
on conflict (case_id) do update set
