values (
  'co-giat-do-sot-cao-tre-em',
  '{"schema_version":"1.0.0","case_id":"co-giat-do-sot-cao-tre-em","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-febrile-seizure-aap-2011","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/21285335/","title":"American Academy of Pediatrics, Febrile Seizures: Guideline for the Neurodiagnostic Evaluation of the Child With a Simple Febrile Seizure, 2011.","organization":null,"year_version":null,"citation":"American Academy of Pediatrics, Febrile Seizures: Guideline for the Neurodiagnostic Evaluation of the Child With a Simple Febrile Seizure, 2011.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-co-giat-do-sot-cao-tre-em-2","resource_type":"other","source":"NICE, Epilepsies in Children, Young People and Adults, NG217, 2022 — mục xử trí trạng thái động kinh co giật.","title":"NICE, Epilepsies in Children, Young People and Adults, NG217, 2022 — mục xử trí trạng thái động kinh co giật.","organization":null,"year_version":null,"citation":"NICE, Epilepsies in Children, Young People and Adults, NG217, 2022 — mục xử trí trạng thái động kinh co giật.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,3,4],"examination_essential_indices":[0,1,6,7],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Co giật do sốt đơn thuần, cơn kéo dài cần cắt cơn","credit":"full"},{"text":"Viêm màng não mủ","credit":"none"},{"text":"Động kinh toàn thể khởi phát sớm","credit":"none"},{"text":"Hạ đường huyết gây co giật","credit":"none"},{"text":"Co giật do hạ canxi máu","credit":"none"},{"text":"Ngộ độc thuốc hoặc hóa chất gây co giật","credit":"none"}]},"action_options":[{"text":"Đặt bé nằm nghiêng an toàn, nới quần áo, hút đờm dãi, giữ thông thoáng đường thở","time_minutes":1,"grade":"critical","rationale":"Bảo vệ đường thở, tránh sặc trong cơn giật."},{"text":"Thở oxy qua mặt nạ, theo dõi SpO2 và nhịp thở liên tục","time_minutes":1,"grade":"critical","rationale":"SpO2 90% và môi tím trong lúc giật."},{"text":"Cắt cơn bằng thuốc nhóm benzodiazepin theo phác đồ nhi khoa, theo dõi nhịp thở sau dùng","time_minutes":2,"grade":"critical","rationale":"Cơn giật đã quá 5 phút nên cần thuốc cắt cơn, không chờ tự hết."},{"text":"Thiết lập đường truyền tĩnh mạch ngoại vi","time_minutes":2,"grade":"recommended","rationale":"Để lấy máu xét nghiệm và dùng thuốc cắt cơn bước hai nếu cần."},{"text":"Hạ sốt bằng paracetamol sau khi hết giật, kết hợp lau ấm","time_minutes":2,"grade":"recommended","rationale":"Giúp bé dễ chịu, nhưng không dự phòng được cơn giật tái phát."},{"text":"Theo dõi tại khoa cấp cứu vài giờ sau cơn, đánh giá lại tri giác và dấu màng não","time_minutes":3,"grade":"recommended","rationale":"Loại trừ nhiễm trùng thần kinh trung ương trước khi cho về."},{"text":"Giải thích cho cha mẹ cách xử trí khi bé giật lại, không nhét vật vào miệng","time_minutes":2,"grade":"recommended","rationale":"Sốt co giật hay tái phát, cần hướng dẫn gia đình."},{"text":"Dùng kháng sinh phổ rộng tĩnh mạch thường quy","time_minutes":3,"grade":"waste","rationale":"Không có bằng chứng nhiễm khuẩn nặng, bệnh cảnh gợi ý nhiễm virus hô hấp."},{"text":"Cho phenobarbital dự phòng kéo dài","time_minutes":2,"grade":"waste","rationale":"Không chỉ định thuốc chống động kinh dự phòng sau sốt co giật đơn thuần."},{"text":"Nhét vật cứng hoặc muỗng vào miệng bé để chống cắn lưỡi","time_minutes":1,"grade":"harmful","rationale":"Gây tổn thương răng, tắc đường thở; bé ít khi cắn lưỡi nguy hiểm."},{"text":"Cho bé uống thuốc hạ sốt và nước trong khi đang co giật","time_minutes":1,"grade":"harmful","rationale":"Nguy cơ hít sặc."},{"text":"Lau người bằng cồn hoặc chườm nước đá","time_minutes":2,"grade":"harmful","rationale":"Gây co mạch, run, hấp thu cồn qua da ở trẻ nhỏ; không hạ sốt hiệu quả."}],"teaching_explanation":"Sốt co giật đơn thuần ở trẻ 6 tháng đến 5 tuổi thường lành tính, nhưng cơn kéo dài trên 5 phút cần cắt cơn ngay và phải loại trừ hạ đường huyết, viêm màng não. Việc đầu tiên là đường thở, oxy và thuốc cắt cơn, không nhét vật vào miệng. Hạ sốt chỉ để bé dễ chịu, không ngăn được cơn giật tái phát."}'::jsonb,
